quests[28344] = { id = 28344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Can You Smell What the Lok'tar is Cooking?", description = "Shortly before you arrived an orc flew in upon a frost wyrm and demanded that I direct him to where the 'newbies were hanging out.' Uncertain as to the vernacular, I told him to fulfill his duty as a member of the Horde and deal with the worgen threat of the area. He grumbled something about 'what the lok'tar was cooking' and headed south to the docks.\n\nOrdinarily I wouldn't care about whether or not an orc went missing, but I am genuinely curious about what the lok'tar might be cooking. Find out.", sourceObjective = "Find Kingslayer Orkus at the Ruins of Southshore in Hillsbrad Foothills.", completion = "*GASP*\n\nHELP!\n\nDROWNING!\n\n*GURGLE*", sourceObjectiveStatus = "unverified-source-field" }
quests[28345] = { id = 28345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "*Gurgle* HELP! *Gurgle*", description = "*GURGLE*\n\nHELP!*GASP*\n\nORKUS IS DROWNING! HELP ME, QUEST GIVER {name}!\n\n*GLUB*\n\nDwarf threw Orkus into the water! Must not die!\n\n*GURGLE*\n\nThe shame would be too great.", sourceObjective = "Help Kingslayer Orkus get out of the water.", completion = "<Orkus' face turns as red as his armor.>\n\nI... uh... the human must have cast some type of mind-altering spell on Orkus. Orkus will explain.", sourceObjectiveStatus = "unverified-source-field" }
quests[28346] = { id = 28346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bachelor", description = "We need to make this work, {name}. The answer is in the blood! Family bonds have kept these Wildhammer clans apart from one another. It'll take family bonds to glue 'em back together. It's a long shot, but we're going to have to play matchmaker!\n\nI'll track down Colin Thundermar and talk with him. You're a smooth one - you should talk to Keegan Firebeard inside. He's sharp enough to understand a political marriage. Go find out if he fancies anyone!", sourceObjective = "Discuss marriage prospects with Keegan Firebeard at Kirthaven in Twilight Highlands.", completion = "What? Kurdran's talkin' marriage!? Didn't he just see me an' ol' Thunderface tearing each other new ones?\n\nThe only eligible Thundermar is Fanny. Now, I'll give you this, she's got the looks allright. All lumpy in the right places, if you hear me. But she's not got that somethun' somethun' a Firebeard looks for in a woman, right?", sourceObjectiveStatus = "unverified-source-field" }
quests[28348] = { id = 28348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormpike Rendezvous", description = "I tracked down the decrepit necromancer, Helcular, in hopes of getting a lead on Alliance movement within Hillsbrad.\n\nHelcular tasked me with finding and killing worgen. Ordinarily this would not be a problem for Orkus, but I had just eaten several helpings of Dirge's Kickin' Chimaerok chops, causing my bowels to cry out in anguish. That's when the trouble began and how I ended up in the water.\n\nHear Orkus out, {name}.", sourceObjective = "Learn about the Stormpike Rendezvous from Orkus.", completion = "I will have my vengeance, but first we must heal Kasha.", sourceObjectiveStatus = "unverified-source-field" }
quests[28349] = { id = 28349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Megs in Marketing", description = "Boss, while you were down at the mines, Megs Dreadshredder in marketing was asking for you. Something about your new ride?\n\nShe's right outside the building to the left.", sourceObjective = "Speak with Megs Dreadshredder at KTC Headquarters on Kezan.", completion = "There he is! I think you're going to like this!", sourceObjectiveStatus = "unverified-source-field" }
quests[28350] = { id = 28350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master Trapper", description = "One thing about me that you might not know, {name}...\n\nI come from a long line of trappers. My father taught me, as his taught him, to master the art of trapping creatures in a most merciful manner.\n\nAs any master trapper will tell you, the most important ingredient in an effective trap is the bait.\n\nSo let's start there.\n\nFill this bucket with the meat scraps from almost any wild creature in Uldum.", sourceObjective = "Sullah wants you to collect 5 Meat Scraps from the wildlife in Uldum.", progress = "Have you got enough to fill my bucket, {name}?", completion = "Fine work, my boy!\n\nYou'll master this trapping skill in no time.", sourceObjectiveStatus = "unverified-source-field" }
quests[28351] = { id = 28351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlimited Potential", description = "Some see the little sand pygmy as nothing more than a pest, a vermin, or worse yet, a vile little demon.\n\nI say they are simply misunderstood!\n\nWith the proper care and guidance, these little fellows may just turn out to be a glorious gift of nature.\n\nI would like you to take these cages and use them to capture a few of them for me to work with.\n\nYou will need to give them a sound beating before boxing them up, but in the end it will be for their own good.\n\nYou'll see!\n\nGo south for pygmies!", sourceObjective = "Use the Reinforced Cage to capture 5 Cavorting Pygmies.", progress = "Did you capture the Pygmies I need, friend?", completion = "Splendid!\n\nThis is shaping up to be better than I had dared to dream!", sourceObjectiveStatus = "unverified-source-field" }
quests[28352] = { id = 28352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camelraderie", description = "Greetings, friend!\n\nYou are always most welcome in my humble tent.\n\nLooking for something to do? Sullah has just the thing!\n\nCamels are good to have in hand regardless, but when putting together a performance the likes of my sideshow, they are an absolute must!\n\nTake this harness and use it to subdue a wandering camel.\n\nYou may have to, uhh, humble it a bit first... if you know what I mean.\n\nYou'll find a desert full of wild camels to the south.", sourceObjective = "Use Sullah's Harness to tame 3 Camels.", progress = "Were you able to tame some camels for me yet, {name}?", completion = "You've done it!\n\nI now have camels to spare. Perhaps one day we shall take our show on the road!", sourceObjectiveStatus = "unverified-source-field" }
quests[28353] = { id = 28353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jonesy Sent For You", description = "Listen, {name}, you may want to make your way back to Jonesy when you get a moment.\n\nChances are, whatever he's got to talk to you about is more pressing than anything I have for you to do.", sourceObjective = "Speak with Harrison Jones in the Oasis of Vir'sar.", completion = "Alright, kid.\n\nMy research is complete. We're about ready to activate the final obelisk.", sourceObjectiveStatus = "unverified-source-field" }
quests[28354] = { id = 28354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kasha Will Fly Again", description = "Kasha will fly again, {name}. She must if we are to claim vengeance! Sadly, Orkus must stay here with Kasha. You must help us. I beg of you!\n\nListen carefully, quest giver. When I first arrived here I flew around for days to learn the lay of the land. There is a farm east of here that has long since been abandoned and is now overrun by gnolls. On this farm grows a special type of mushroom known as the mudsnout. Go to the stead and gather mudsnout for Kasha. Return here when your pack is full.", sourceObjective = "Gather 8 Mudsnout Blossoms.", progress = "Have you recovered the mudsnout?", completion = "This mushroom is toxic to living things, but provides a restorative boost to the undead. Let us see how Kasha reacts.", sourceObjectiveStatus = "unverified-source-field" }
quests[28355] = { id = 28355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrible Little Creatures", description = "Gnolls! These terrible little creatures are a blight upon any land - which is saying a lot when you consider that Hillsbrad is Forsaken territory. Kill as many of the gnolls at the Nethander Stead as you can. For the good of the world!", sourceObjective = "Kill any 10 Gnolls at the Nethander Stead.", sourceObjectiveStatus = "unverified-source-field" }
quests[28356] = { id = 28356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preemptive Strike", description = "These plans document what appears to be an imminent attack on Southshore. The naga of the Eastern Strand are planning to take over the town now that the Alliance has been pushed out.\n\nNot if you can help it!\n\nKill all of the naga on the Eastern Strand and report to Helcular at the Ruins of Southshore with the Daggerspine attack plan.", sourceObjective = "Kill any 15 Naga at the Eastern Strand.", completion = "HAH! Those naga have some balls on them! To think that they could take Southshore from us in our own territory! Such a preposterous notion.\n\n<Helcular laughs.>\n\nYou have done well to thwart their attack - though I do wonder if they could have survived for even a minute in the blight.", sourceObjectiveStatus = "unverified-source-field" }
quests[28357] = { id = 28357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take it to the Tree", description = "Those mangy curs think they can just snoop around my site and get away with it? I'll show them...\n\nAnd what I mean by that is, of course, that YOU will show them. You and the small army of axe-wielding goblin hires I've sent to Talonbranch Glade.\n\nThe place will be swarming with worgen by now. Just where we want them. Head to the southeast, join up with the rest of our forces, and let some fur fly.", sourceObjective = "Slay 8 Talonbranch Defenders.", completion = "Let's hope we put down enough of them to get the message across.", sourceObjectiveStatus = "unverified-source-field" }
quests[28358] = { id = 28358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting the Damned", description = "The first demons to set foot in this forest were infernals. Long ago, these powerful beings of stone and demonic fire fell from the sky to take this land for the Burning Legion.\n\nThe charred craters of Shatter Scar Vale to the south are where these infernals landed, and many still wander there. They are fierce foes, and killing them is both a worthy challenge and a noble cause.\n\nI offer reward for those who join the hunt. Return here afterwards.", sourceObjective = "Slay 6 Infernal Sentries.", completion = "I thank you for hunting in my stead, {class}.\n\nI've found I must pace myself... finding too much thrill in hunting demons is a dangerous path.", sourceObjectiveStatus = "unverified-source-field" }
quests[28359] = { id = 28359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Core of Kroshius", description = "The most fearsome demon in Shatter Scar Vale is known as Kroshius. Though many have hunted him over the years, destruction has only made him stronger.\n\nTime after time, warlocks have come to this forest and reanimated Kroshius. He now lurks in the southeast, surrounded by demonic fire, awaiting any who come to try and claim his power.\n\nI will not have this corrupt cycle continue! Kill Kroshius, and bring his infernal core to me.", sourceObjective = "Obtain Kroshius' Infernal Core.", progress = "The core must be kept away from Shatter Scar Vale.", completion = "This foul chunk is what those warlocks sought year after year. I will protect it myself, or destroy it if possible, and ensure Kroshius never rises again.", sourceObjectiveStatus = "unverified-source-field" }
quests[28360] = { id = 28360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Running Their Course", description = "I'd love so much to save every creature in the forest, but as you probably have seen, some are just too far gone.\n\nWhen we first founded Whisperwind Grove, the woods just to the south were full of beautiful coursers, majestic and gentle creatures. The corruption here hasn't made them violent, but they've wasted away to nearly nothing.\n\nEven if they were cleansed, they would know only pain and suffering. Please, {class}, help put them down for me.", sourceObjective = "Slay 8 Felrot Coursers.", completion = "Thank you, {name}. They won't spread the corruption any further, and they won't be in pain either.", sourceObjectiveStatus = "unverified-source-field" }
quests[28361] = { id = 28361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Squirrely Clean", description = "The larger animals are often too far corrupted to save, but you'd be surprised how hardy the little ones are.\n\nTake the squirrels, for example. After washing in corrupted water, they can spread illness far from the original source, but it's slow to affect the squirrels themselves. In fact, a simple washing will result in a clean squirrel and a safer forest!\n\nHere, take this bottle of cleaning mixture. Grab and scrub any squirrel you see in the woods to the south... they'll be thankful for it!", sourceObjective = "Scrub 6 Tainted Squirrels.", completion = "Aren't they just adorable?\n\nIt's those little victories that keep me going. We'll save this forest one squirrel at a time.", sourceObjectiveStatus = "unverified-source-field" }
quests[28362] = { id = 28362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stupid Drizle!", description = "Stupid, stupid Drizle! I told him not to go!\n\nDrizle wanted to steal more honey from Felpaw Village... you know, just west of here? You can see it from the cliff...\n\nAnyway... I told him it was a dumb idea but he went anyway, and then the Deadwood tribe got him, and... and...\n\nSniff...\n\nI don't know what they're gonna do! Please find him, <Mr./Ms.> {race}! Even if he is a dummy! I don't want Drizle to get eaten!", sourceObjective = "Find Drizle in Felpaw Village.", completion = "Help! Please help!", sourceObjectiveStatus = "unverified-source-field" }
quests[28363] = { id = 28363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stirred the Hornet's Nest", description = "Wow!\n\nIt sounds like you really got their attention, {name}. We're never getting in there with them on alert like this.\n\nThere must be a way...\n\nIt's just a matter of time before Schnottz's men activate the obelisk and I need to research the scrolls you found. I need you to figure this one out without me.\n\nSullah has connections in these parts. Maybe he has a solution for getting us inside.", sourceObjective = "Speak to Sullah at Sullah's Sideshow.", completion = "You know, I believe I have just the thing!", sourceObjectiveStatus = "unverified-source-field" }
quests[28364] = { id = 28364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chieftain's Key", description = "Sniff... I'm sorry! I didn't mean to get caught! They grabbed me and put this chain on me and left me here! I can't move and my leg fell asleep and I'm hungry!\n\nThe chief has the key... Chieftain Bloodmaw, the other ones said. He's in the north end of the camp.\n\nBut hurry! Please! Don't leave me alone here!", sourceObjective = "Retrieve Drizle's Key from Chieftain Bloodmaw.", progress = "Did you get the key?", completion = "Thank you, thank you! I'm getting out of here right away!\n\nAnd if Ferli sent you here... don't tell her I was crying!", sourceObjectiveStatus = "unverified-source-field" }
quests[28365] = { id = 28365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "<PH>Drizle Safe" }
quests[28366] = { id = 28366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disarming Bears", description = "I would prefer to do as much as we can to protect my people from the Deadwood tribe without slaughtering every last one of them. We've taken steps towards this before, and if you wish to prove yourself to the Timbermaw tribe, I would ask you do this as well.\n\nLook for the piles of weapons kept in Felpaw Village to the southwest. Take as many as you find. If we disarm the Deadwood tribe, we may be able to stop some bloodshed later.", sourceObjective = "Collect 7 Deadwood Weapons from Felpaw Village.", progress = "Do you have the weapons?", completion = "Thank you, {race}. An action like this will go a long way towards proving yourself as an ally of the Timbermaw.", sourceObjectiveStatus = "unverified-source-field" }
quests[28367] = { id = 28367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shroud of the Makers", description = "It is good to have friends, {class}! While kindness is its own reward, there can be tangible benefits too!\n\nSome friends of mine recently intercepted a shipment of Schnottz's plunder and found something that should serve your needs nicely.\n\nIt's a piece of titan technology that renders the user nearly invisible. If you use it in the enemy camp, you might be able to rewire their explosives and make a mess of their operation.\n\nEach charge has a limited duration, so don't stray too far from safety!", sourceObjective = "Sabotage 7 Schnottz Powder Kegs.", completion = "Hah!\n\nI heard it from here! I wish I could've been there to see it!", sourceObjectiveStatus = "unverified-source-field" }
quests[28368] = { id = 28368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire in the Hole!", description = "Land's sakes, pardner! You done shut off those valves but good.\n\nUnfortunately we've had a critical blowout in our gosh-darned central burnoff regulator! Missus Darla's done sent as many workers as she can rustle to go shut it off, but those flames have a mind of their own!\n\nLiterally! They're hoppin' up and grabbin' anyone who comes near! So Darla says if you can muster up out of that cave you're in and beat that elemental, she's got a mighty fine prize in store for ya!", sourceObjective = "Slay Grolvitar the Everburning.", completion = "Well, my entire operation's nearly been ruined. But you came through in the clinch, {name}.\n\nIt could've been worse! I gotta hand it to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[28369] = { id = 28369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Sister, Fanny", description = "Before you go, be sure to stop by the inn behind me. My sister Fanny is inside.\n\nRefugees are pouring into Thundermar from all of the torched Wildhammer settlements around us, and I put Fanny in charge of 'em. She's tough as talons, that one. But she might need your help.", sourceObjective = "Talk to Fanny Thundermar at Thundermar in Twilight Highlands.", completion = "Me brother sent you? Good! I could use a {class}. Can ya hold yer own in a fight?", sourceObjectiveStatus = "unverified-source-field" }
quests[28370] = { id = 28370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wisp-napping", description = "Can you believe these worgen here have wisps?  The night elves showed them all that druid junk and now they've got their precious little wisps too, giving them all the building material they want without having to harm any precious trees.\n\nIf we had those things, we could pull extra wood out of every tree in our site. Free resources, free profit! That's why I've been working on this containment device.\n\nHead to Talonbranch Glade and use it to steal some wisps. Just point and press the button.", sourceObjective = "Use Darla's Wisp Magnet to collect 5 Talonbranch Wisps.", completion = "Pretty little things, aren't they? I wonder if we can figure out how to make more of them.", sourceObjectiveStatus = "unverified-source-field" }
quests[28372] = { id = 28372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Business", description = "All this happy friends stuff is great, isn't it? People working together, healing the forest. But what's gonna happen to the forest when it's healed? It's just gonna sit there?\n\nWe need this lumber. The Horde needs it. I've got orders here to send as many loyal Horde soldiers--and I'm sure you're loyal--up north to Irontree Clearing.\n\nI've already arranged for the hippogryph master to give you a free ride over there. Talk to Darla Drilldozer when you touch down.", sourceObjective = "Take a flight to Irontree Clearing and speak with Darla Drilldozer.", completion = "Fez sent you, hmm? At least he's good for something.", sourceObjectiveStatus = "unverified-source-field" }
quests[28373] = { id = 28373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timbermaw Hold", description = "Okay, I know this is a longshot, but I figure it never hurts to ask.\n\nWhile I deal with the fallout of all the ridiculous nonsense that just went on here, I need you to go speak to some bears. The Timbermaw furbolg control the forests to the northeast, and they're not too fond of us.\n\nI just need someone to give them the idea the Horde isn't all that bad. Head northeast up the road to Timbermaw Hold--don't go into Felpaw Village--and ask the furbolg outside if they have any favors they'd like done.", sourceObjective = "Speak with Nafien at Timbermaw Hold in Felwood. Timbermaw Hold is to the east, past Felpaw Village.", completion = "We furbolg are not foolish, {name}. We will not yield Timbermaw Hold to any askers.\n\nHowever, we are also in dire need of assistance. If you help us, we will grant you our favor and allow you passage.", sourceObjectiveStatus = "unverified-source-field" }
quests[28374] = { id = 28374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weeding the Lawn", description = "In a place like this, even something as simple as growing flowers and pulling weeds can require some heroic effort.\n\nThe orchid lashers that grow on all sides of the grove are a sign of healing. But they're not flawless; some of them do succumb to demonic corruption now and then.\n\nI've found the best way to check is to just pull them up. If they're normal, they'll wander around a bit and reroot themselves. If they aren't... well, you'd better be ready for a fight!", sourceObjective = "Pull up 7 Whisperwind Lashers to check them for corruption.", progress = "Checking the lashers will really help me here.", completion = "It's hard work, but it's so rewarding when you see them growing up big and strong.\n\nWhen they're not covered with demonic thorns, that is!", sourceObjectiveStatus = "unverified-source-field" }
quests[28375] = { id = 28375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Road to Purgation", description = "The time of vengeance has come, {name}. Kasha can once more fly, thanks to you. She will take us to Purgation Isle so that we may confront the Stormpike dwarf general, Vanndar Stormpike, and his captain, Balinda Stonehearth. BOTH will pay for what they have done.\n\nAre you ready? Orkus cannot do this alone.", sourceObjective = "Accompany Kingslayer Orkus to Purgation Isle.", completion = "This place is dark... foreboding. It smells of piss and fur. There are definitely worgen here and very likely dwarves.", sourceObjectiveStatus = "unverified-source-field" }
quests[28376] = { id = 28376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Myzerian's Head", description = "The head of one of Deathwing's most formidable black dragons is now in your possession.\n\nWhile many in Azeroth would pay dearly for such an artifact, something tells you that it belongs in a museum for all to see and remember.\n\nHarrison Jones is likely to have the proper connections.\n\nSullah would certainly be happy to deliver it to him.", sourceObjective = "Take Myzerian's Head to Sullah at Sullah's Sideshow.", progress = "You took down that dragon!?\n\nRemarkable!", completion = "Quite an accomplishment, {name}.\n\nI'll be certain that this gets to Harrison when his expedition here is concluded.", sourceObjectiveStatus = "unverified-source-field" }
quests[28377] = { id = 28377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue at Glopgut's Hollow", description = "Well speak of the devil in a blue dress. Fanny's gone and gotten herself kidnapped by ogres!\n\nI don't trust the Thundermars to be able to mount a rescue on their own. I'll round up my gryphon riders and provide some air support.\n\nI'm sure they can use an extra {class} down there, {name}. Grab your gear and look for Colin Thundermar in the Glopgut ogre camp. It's southwest of here, below the cliffs. Hurry now!", sourceObjective = "Find Colin Thundermar at Glopgut's Hollow in Twilight Highlands.", completion = "Good to have you fighting at my side again, {name}!\n\nAnd I see the Firebeards have come as well. I suppose they'll provide a distraction while me and my boys do the heavy lifting.", sourceObjectiveStatus = "unverified-source-field" }
quests[28378] = { id = 28378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Fanny", description = "We've started tearing this camp apart, {name}, but there's no sign of Fanny. Maybe you can find her.\n\nWe haven't checked the cave just behind me, to the northwest. See if you can find Fanny in the cave!", sourceObjective = "Find and rescue Fanny Thundermar.", progress = "Do you see that? The Firebeards are supporting us from the air. It's about time.\n\nHave you found my sister yet?", completion = "Fanny is safe! I hear Firebeard was in there with you? Nice to hear he's finally pulling his weight.\n\nWait, why are you looking at me like that, {name}? Do you know something I don't?", sourceObjectiveStatus = "unverified-source-field" }
quests[28379] = { id = 28379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Bashin'", description = "Glopgut ogres! I'd say they was dumb as a sack of hammers, but I have more respect for me hammers than that.\n\nWe've fought off their raids for years, but if they're bold enough to steal one of our own, we're gonna have to learn them a lesson.\n\nHelp us smack around some Glopgut ogres! Kill their pounders, hurlers, or bashers either out here or - better - inside the cave. That'll show 'em.", sourceObjective = "Kill 10 Glopgut ogres (either Glopgut Pounders, Glopgut Hurlers, or Glopgut Bashers).", progress = "Walp? Got a few more notches on yer weapon to show off?", completion = "Har! My men could learn a lot by watching you work. Well done.", sourceObjectiveStatus = "unverified-source-field" }
quests[28380] = { id = 28380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pikwik in Peril", description = "What the heck is going on here? Foreman Pikwik should've shut the valves off by now.\n\nWe can cap these leaks all day and if the central valve is off, we're just delaying an enormous explosion.\n\nListen, if you value money, your life, or either combination of the two, you'd better head south to Irontree Cavern and see if you can find Foreman Pikwik.", sourceObjective = "Speak with Foreman Pikwik at Irontree Cavern.", completion = "It's a disaster down here! The pump's thrown, all my men in there are gone...\n\nYou gotta help!", sourceObjectiveStatus = "unverified-source-field" }
quests[28381] = { id = 28381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Denmother", description = "Barely a crow's flight to the north, goblins ravage this forest, clearcutting it to fuel the war machines of the Horde and line their own pockets. This one pays enough pleasant words and crafted lies to the druids here for them to turn a blind eye, afraid to disturb the tenuous neutrality here.\n\nThe worgen of Talonbranch Glade have had enough. Join us! The hippogryph master can take you directly to our home. Denmother Ulrica will welcome any {race} who wishes to fight.", sourceObjective = "Take a flight to Talonbranch Glade and speak with Denmother Ulrica.", completion = "Welcome to the home of my pack, {class}. Prepare yourself for war.", sourceObjectiveStatus = "unverified-source-field" }
quests[28382] = { id = 28382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemy at our Roots", description = "The goblins are already upon us!\n\nWe have tried everything in our power to warn the goblins to leave Irontree Clearing before we resorted to violence. As they turned a blind ear to us, we struck, and now rather than spare the forest they would lay down their lives for greed.\n\nThey will soon know the full extent of our fury! The battle rages just beyond our northern gate. Join our pack in glory and slay any goblin who dares come before us!", sourceObjective = "Slay 8 Irontree Choppers.", completion = "May their blood water our tree. You fight well, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28383] = { id = 28383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wisps of the Woods", description = "I have toiled long here with the Denmother to spread the teachings of Cenarius and the ways of the wild. She has gained much of my trust, and in return, I have been allowed to introduce the spirits of the forest to her students. The company of wisps is a great honor, as well as a useful blessing.\n\nBut now the goblins descend on us, and seek to steal the wisps for nefarious use. Please, prevent this blasphemy!\n\nCall the wisps back here from the western woods with this blessed branch, and keep them safe.", sourceObjective = "Use the Swiftwind Switch to collect 5 Talonbranch Wisps.", progress = "Have the wisps been saved?", completion = "Thank you, {name}. Now the Horde will not be able to defile these poor spirits to aid their brutish ways.", sourceObjectiveStatus = "unverified-source-field" }
quests[28384] = { id = 28384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Clearing", description = "Irontree Clearing must be razed. We can afford no mercy if we want to prevent the goblins from spreading their destruction through the entire forest.\n\nAlton Redding, my most trusted protector, has already led much of the pack around the enemy line to strike while they are distracted here. Seek him out to the west, overlooking Irontree Cavern.", sourceObjective = "Speak with Alton Redding near Irontree Cavern", completion = "Welcome to the pack, {race}. Let's hope you don't mind getting a bit uncivilized.", sourceObjectiveStatus = "unverified-source-field" }
quests[28385] = { id = 28385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oil and Irony", description = "I plan to use the goblin's greed and pollution against them. Any further despoiling of the land they have already carved here will be worth it to stop their further spread.\n\nDeep within Irontree Cavern, just below us, runs many pipes to pump oil through the ground across the entire clearing. These pipes are attached to a master control pump in the very back of the cavern.\n\nEnter the cavern and sabotage the pump. The ensuing havok will give us opportunity for our final strike.", sourceObjective = "Sabotage the Master Control Pump at the bottom of Irontree Cavern.", completion = "You flip a few switches on the pump and crank a large handle all the way to the right. There's a shuddering rumble in the nearby walls.", sourceObjectiveStatus = "unverified-source-field" }
quests[28386] = { id = 28386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Borrowed Bombs", description = "The workers in Irontree Cavern below us have been driven out already. Something else has overtaken the cave.\n\nThis works in our favor. I spotted at least a few of them dropping explosives as they fled... explosives we'll need for the next part of our plan.\n\nEnter the cave and salvage any abandoned bombs you can find. When you're finished with that and the pump, we'll begin our final assault.", sourceObjective = "Collect 8 Irontree Explosives from Irontree Cavern.", progress = "Was I right? How many did you find?", completion = "Perfect. I've had the pack gather explosives from the rest of the camp as well, and with these, we'll have just enough to get things started once the oil is flowing.", sourceObjectiveStatus = "unverified-source-field" }
quests[28387] = { id = 28387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burnout", description = "Your pump sabotage has caused pipes to break all over camp. The goblins are in a panic over the geysers, and it's about to get worse.\n\nTake the gathered explosives and use them to set the geysers aflame. We're going to do as much damage to the camp as we can, and keep that oil from being used to fuel shredders... or worse, Horde warships.", sourceObjective = "Use the Stolen Irontree Explosives to ignite 7 Oil Geysers in Irontree Clearing.", completion = "Look at them run... the live ones, that is. Glorious.", sourceObjectiveStatus = "unverified-source-field" }
quests[28388] = { id = 28388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloody Wages", description = "Sad little cowards... look at them flee in panic!\n\nDon't let it fool you, {name}. The second they've regained their wits, those goblins are going to spend every waking moment chopping this forest to bits and sending the pieces to the Horde's war effort.\n\nDon't give them the chance. Kill the workers throughout Irontree Clearing without mercy... show them their greed has a price!", sourceObjective = "Slay 7 Panicking Workers.", completion = "Serves every last one of them right. Let's hope those in charge send the rest of their greedy scavengers somewhere else.", sourceObjectiveStatus = "unverified-source-field" }
quests[28389] = { id = 28389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to the Denmother", description = "With the goblins scattered and their equipment destroyed, they'll either get the message and leave, or be easy pickings if they choose to stay. We've won here.\n\nYou've fought as fiercely as any member of the pack, {name}. Return to the Denmother and let her know of our success. I'll be maintaining my watch.", sourceObjective = "Speak with Denmother Ulrica at Talonbranch Glade.", completion = "Let the goblins and all the Horde know we will not have offers of peace and sanctuary abused... most of all not in our new home.\n\nI am grateful my people have found allies as bold as you, {name}. This reward will represent your bond with our pack. You will always be welcome here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28390] = { id = 28390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glop, Son of Glop", description = "Glop had a son. In his grave hubris, he named it Glop. And so the line of fungalmancers continues.\n\nI require you to slay this new fungalmancer. Your shaman ally has already returned, and awaits you at his cave in the southwest of Verlok Stand.", sourceObjective = "Speak to Earthmender Norsala, then kill Fungalmancer Glop.", progress = "To this day, I do not understand how filthy stone troggs breed so quickly. Perhaps it is better that it is left that way.", completion = "Perhaps one day, we shall slay these stone troggs more swiftly than they can breed, and in so doing, end the line of fungalmancers forever.\n\nIn time.", sourceObjectiveStatus = "unverified-source-field" }
quests[28391] = { id = 28391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Restless Brood", description = "Aeosera is restless and stubborn. She scoffs at our dominance, and she needs to be reminded of her place.\n\nI still have the mallet you retrieved for me. Return to the western edge of the Pale Roost and strike the resonating crystal.\n\nI will meet you there and lend what aid I can. Put her back in her place, {class}.", sourceObjective = "Defeat Aeosera.", progress = "And so continues the cycle of the stone drakes. Tumultuous wills in stoic frames.", completion = "You are quite skilled at bending the dragon's will, {race}. I would be jealous of your agility, except that it comes with such a fragile frame.", sourceObjectiveStatus = "unverified-source-field" }
quests[28392] = { id = 28392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Timbermaw Tribe", description = "The Timbermaw furbolg are the last known tribe of uncorrupted furbolg. They huddle on the edge of these lands, ferociously defending their home of Timbermaw Hold.\n\nThough they are proud creatures, they are in need of much assistance. Should you wish to help, follow the road north from here, and seek them out at the entrance to Timbermaw Hold.", sourceObjective = "Speak with Nafien at the entrance to Timbermaw Hold.", completion = "The druids of Talonbranch Glade have assisted us before. We are still unused to \"friendly\" worgen in these woods, but our people are also familiar with the sorrows of curses and corruption...\n\nSorrows that I hope you can aid us in, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28393] = { id = 28393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dangerous Alliance", description = "SI:7's latest report about Twilight's Hammer and Dark Iron activity worries me, {name}. There's evidence that they are preparing a joint attack from within Blackrock Mountain. We'll be hard-pressed to turn back such a combined force, but if we act before they're ready to strike, we might be able to blunt the attack.\n\nYou must go into Blackrock Depths and capture the Twilight's Hammer attack plans from General Angerforge in the West Garrison. Do not hesitate to take out the elementals supporting his forces.", sourceObjective = "Kill 6 Fireguard Destroyers and recover the General's Attack Plans from General Angerforge at the West Garrison in Blackrock Depths.", progress = "We cannot afford to allow the Dark Iron dwarves to ally with Twilight's Hammer.", completion = "I'll send these plans to the king and his strategists immediately. If the Dark Irons and their Twilight allies manage to recover and attack, our men will be ready for them. Well done, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28394] = { id = 28394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Golem Lord's Creations", description = "The latest SI:7 intelligence on Blackrock Depths is troubling, {name}. It appears Twilight's Hammer is working with the Dark Iron engineer, Argelmach, to create war golems powered by elementals. These golems could prove to be a devastating weapon if used against us.\n\nYou must prevent that from happening, {name}. Find the Manufactory in Blackrock Depths, capture the blueprints he's using to make those golems, and recover the elemental modules he's using to power them.", sourceObjective = "Obtain 5 Elemental Modules from the golems in the Manufactory of Blackrock Depths and recover the Elemental Golem Blueprints.", progress = "We cannot afford to allow those golems to be used against us.", completion = "I know a couple of engineers who will want to take a look at those plans. They won't be using these golems anytime soon. Good work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28395] = { id = 28395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feathers for Nafien", progress = "While you have proven yourself to me, you may need to continue to work toward proving yourself to the suspicious brethren of my tribe.  To that end, I may be able to continue assisting you.\n\nSome of the Deadwood furbolgs wear a distinctive headdress that may be used as a means of proof in thinning their numbers.  Bring me a feather from any headdresses you acquire; for every set of five you bring me, you will earn recognition amongst the Timbermaw.", completion = "Well done, {name}!  I will make sure that your deeds are known amongst my kind.\n\nRemember to bring any of the feathers you find to me.  I will continue to accept them as long as necessary." }
quests[28396] = { id = 28396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feathers for Grazle", progress = "While you have proven yourself to me, you may need to continue to work toward proving yourself to the suspicious brethren of my tribe.  To that end, I may be able to continue assisting you.\n\nSome of the Deadwood furbolgs wear a distinctive headdress that may be used as a means of proof in thinning their numbers.  Bring me a feather from any headdresses you acquire; for every set of five you bring me, you will earn recognition amongst the Timbermaw.", completion = "Well done, {name}!  I will make sure that your deeds are known amongst my kind.\n\nRemember to bring any of the feathers you find to me.  I will continue to accept them as long as necessary." }
quests[28397] = { id = 28397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Will Never Expect This...", description = "They made a mistake by not killing me when they had the chance. Perhaps they thought Orkus would drown. HAH! Now they will pay the price for their carelessness.\n\nYou and I will tear this island apart, {name}. They will never expect this! Once all of their soldiers are dead we will confront the leaders. Be on the lookout for attack plans. If we can get our hands on their plans we will be able to put a stop to their whole invasion!\n\nLet's go, {name}!", sourceObjective = "Kill 8 Stormpike Dwarves and 8 Bloodfang Sentries on Purgation Isle.", progress = "We will kill them all!", completion = "Look upon the carnage, {name}. You and I make quite the team!\n\nNow to find those plans and deal with their leaders.", sourceObjectiveStatus = "unverified-source-field" }
quests[28398] = { id = 28398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pyromancer's Grimoire", description = "The power of the Dark Iron forces and their Twilight's Hammer allies is growing within Blackrock Mountain. Pyromancer Loregrain, a magus of renown, plays an important role in leading the Twilight's Hammer forces there. If we could get our hands on his grimoire, I might be able to devise counterspells and other ways of dampening their elemental magics.\n\nYou must descend into Blackrock Depths, locate the Shrine of Thaurissan, and capture the grimoire. Show Loregrain and his Twilight minions no mercy.", sourceObjective = "Kill 6 Twilight Emissaries and recover Loregrain's Grimoire from Pyromancer Loregrain at the Shrine of Thaurissan in Blackrock Depths.", progress = "Have you managed to capture the pyromancer's grimoire?", completion = "<The {class} trainer pages through the grimoire quickly.>\n\nI've already seen a dozen spells I never knew existed. This will be most helpful, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28399] = { id = 28399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stones of Binding", description = "I have it on good authority that SI:7 is concerned about collaboration between Twilight's Hammer and the Dark Iron dwarves in Blackrock Depths. We can act on this information, prove our value to the Alliance, and gain something for ourselves at the same time.\n\nThe report mentions that the Twilight's Hammer followers have placed a number of elemental binding stones throughout Shadowforge City, the Domicile, the Shrine of Thaurissan, the West Garrison and the East Garrison. Find and capture those stones!", sourceObjective = "Recover 6 Elemental Binding Stones from Blackrock Depths. You can find the stones in Shadowforge City, the Domicile, the Shrine of Thaurissan, the East Garrison, and the West Garrison.", progress = "Have you managed to find those binding stones?", completion = "The binding stones you brought back are exceedingly powerful. It will likely take me years to learn all their secrets, but I'm certain they'll prove most useful. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28400] = { id = 28400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroes of the Horde!", description = "Now to find their battle plans and take out their leaders! Should we succeed there is an orc high warlord who served in the war in Silverpine that is now stationed at Tarren Mill - located in the heart of Hillsbrad. He will grant both of us commendations for this! We will be heroes of the Horde, {name}!\n\nOnward! Together we will defeat the Alliance filth!", sourceObjective = "Steal the Alliance Battle Plans and Become Heroes of the Horde.", progress = "<High Warlord Cromush looks somber.>", completion = "<High Warlord Cromush salutes.>\n\nHe will be honored as a hero of the Horde, just as he always hoped. What you and Orkus did will save hundreds of lives and ensure that our foothold in Hillsbrad is not lost.", sourceObjectiveStatus = "unverified-source-field" }
quests[28401] = { id = 28401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaves of the Firelord", description = "Within the halls of Blackrock Depths, the Twilight's Hammer cult and the Dark Iron dwarves are gathering their forces. Backing up their legions are hordes of fire elementals bound to the service of the firelord, Ragnaros.\n\nIf we can free those elementals from their bonds, we can both weaken our enemies and honor the elements. Take this totem with you and use it on subdued fireguards. It will free their spirits from their bondage and restore them to their natural state.", sourceObjective = "Use the Totem of Freedom to free the essences of 6 Fireguards, Fireguard Destroyers, or Blazing Fireguards in Blackrock Depths.", completion = "You have truly served both the Alliance and your calling as a {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28402] = { id = 28402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnottz So Fast", description = "I'm nearly ready, {name}.\n\nYour scrolls contained enough information to discern their encryption method. Now all that's left is for me to translate the codes.\n\nI need you to scout out the chamber beneath the Obelisk of the Moon. There are likely to be a few of Schnottz's troops down there that escaped your blast.\n\nYou take care of them and I'll meet you there when I'm finished.", sourceObjective = "Kill 10 Schnottz Elite Troopers in the Chamber of the Moon.", completion = "Alright, {name}.\n\nI think everything is in order. Let's do this!", sourceObjectiveStatus = "unverified-source-field" }
quests[28403] = { id = 28403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad Datas", description = "There should be two titan communication devices in this chamber.\n\nIf my translations are correct, one is a death trap and the other will accept the codes and activate the obelisk.\n\nLet's hope I get this right.\n\nLet me know when you're ready.", sourceObjective = "Accompany Harrison Jones in the Chamber of the Moon.", completion = "Okay, {name}.\n\nI think I can do this manually, but I'll need your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[28404] = { id = 28404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'll Do It By Hand", description = "Yes, this all looks familiar enough.\n\nThanks to all the information you gathered for me, I'm sure that I can activate the mechanism. I'll just need some time free from distraction.\n\nAs soon as I get started, you can count on that titan construct to try and stop me.\n\nThat's where you come in.\n\nI don't need to remind you of what's riding on this. Take down that guardian!", sourceObjective = "Defeat the Titanic Guardian.", progress = "Almost got it...", completion = "That should do it.\n\nStand back!", sourceObjectiveStatus = "unverified-source-field" }
quests[28405] = { id = 28405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of Darkness", description = "Blackrock Depths has long been home to our enemies, but now SI:7 sends word that the Dark Irons and Twilight's Hammer are increasing their collaboration. Using the knowledge of the cult, the Dark Iron dwarves are imbuing their weapons with elemental powers. They've outfitted the Anvilrage legion with these fearsome new weapons.\n\nI want you to go into Blackrock Depths and gather the weapons from the Anvilrage dwarves there and break them over the Black Anvil in the heart of Shadowforge City.", sourceObjective = "Capture 5 Elemental-Imbued Weapons from Anvilrage dwarves in Blackrock Depths, then break them over the Black Anvil in Shadowforge City.", completion = "Thanks to your efforts, those weapons will never shed Alliance blood. Excellent work, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28406] = { id = 28406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Iron Army", description = "Things are getting interesting in Blackrock Mountain, {name}. Our sources report that the Dark Iron dwarves have formed closer ties with Twilight's Hammer and both are preparing for a major offensive.\n\nI've made the contents of the report known to key leaders in Stormwind and I want you to help deal with this emerging Dark Iron threat.\n\nThe rations for most of the Dark Iron army are kept in the East and West Garrison of Blackrock Depths. Take this poison and apply it to their grain reserves.", sourceObjective = "Use the Fast-Acting Poison to contaminate 6 Grain Rations in the West Garrison or East Garrison of Blackrock Depths.", completion = "With any luck, the poison will take out a fair number of their frontline troops before they know what's happening. That should stall them for the near future. SI:7 is most pleased with your work.", sourceObjectiveStatus = "unverified-source-field" }
quests[28407] = { id = 28407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bachelorette", description = "Firebeard? Marry my sister!? I swear the world's gone mad, {name}!\n\nStill, maybe Kurdran is right. A nice normal wedding would ease everyone's mind... and maybe cool off Firebeard a little. It was great to actually work together here against the ogres.\n\nRight then! It's all up to Fanny. Something tells me she won't want to be tied down.\n\nFly back to Kirthaven and see if she's game. I'll finish up the nasty business with the ogres here.", sourceObjective = "Talk to Fanny at Kirthaven in Twilight Highlands.", completion = "<Fanny throws her arms up, exasperated.>\n\nYou, Kurdran, Firebeard, and now my brother - everyone's got wedding fever!\n\nFine, fine, I'll marry Keegan Firebeard. But only 'cuz he's strong and handsome, with a jaw that can cut gravel and an arse like an anvil. Not for any political reasons.\n\nWe're going to need your help, though. We got a whole lotta wedding to put together, and not a lot of time to do it.", sourceObjectiveStatus = "unverified-source-field" }
quests[28408] = { id = 28408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Bold", description = "By tradition, Wildhammer brides wear white to show their purity. In addition, they wear a crown of black feathers - to show their CHUTZPAH.\n\nOwl feathers make the boldest statement, and Fanny deserves nothing less. Tawny owls are native to the Highlands. Look for them circling near trees that grow along the cliffs, and take their feathers.\n\nYou'll probably want to kill 'em, first.", sourceObjective = "Collect 12 Pristine Owl Feathers.", progress = "Have you Fanny's feathers?", completion = "Ah, you work fast. Bold feathers for a bold woman. Well done!", sourceObjectiveStatus = "unverified-source-field" }
quests[28409] = { id = 28409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Brewed", description = "It would be an insult to celebrate a Wildhammer wedding without drink. Kurdran himself called for a few kegs of rare Thunderbrew Lager to be sent ashore from Highbank, but the caravan can't get through the pass.\n\nFollow the road east of here, around the south side of Thunderstrike Mountain, and catch up with the caravan. Look for a fellow named Hammelhand, and help him get the booze through the pass!", sourceObjective = "Speak with Hammelhand on the road East of Kirthaven, and escort a supply caravan back to town.", completion = "Ahh, Russell the Bard is always raving about Thundermar Lager. I guess it doesn't have the kick of a good Wildhammer brew, but he goes on and on about the \"body\" or \"flavor.\" I guess we'll find out, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[28410] = { id = 28410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Stolen", description = "Everyone's going to want to dress their best for this, and finery is in short supply in the Highlands.\n\nI understand that those goblin wretches off the coast use the finest silk for repairing their zeppelin air envelopes. A waste!\n\nFind a zeppelin flying back and forth between Dragonmaw Port and the Krazzworks, and liberate some silk from the cargo hold in the lower decks.", sourceObjective = "Collect a bolt of Fine Dark Cloth.", progress = "How did the air raid go?", completion = "Oh, aye! Kilts for the gents, gowns for the bridesmaids.\n\nJust don't tell the ladies they're wearing clothes fit for a blimp.", sourceObjectiveStatus = "unverified-source-field" }
quests[28411] = { id = 28411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something Stewed", description = "Finally, we're going to need a feast. And none of that \"finger food\" stuff! This crowd wants meat, and lots of it.\n\nGather up venison from Highland elk and does. Highland worg are good eatin' too - bring back some ribs. We'll show you a feast like you've never had in all the Eastern Kingdoms, friend.", sourceObjective = "Gather 8 slabs of Fresh Venison and 5 Worg Ribs.", progress = "What's the food situation, {name}?", completion = "Lookat that! You're practically bent double under the weight of all that meat. I'd better get my people cooking.", sourceObjectiveStatus = "unverified-source-field" }
quests[28413] = { id = 28413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words and Music By...", description = "I've written many an epic tune in my lifetime, {name}, but this upcoming wedding deserves a very special ballad. And fast!\n\nShould I write a love song? A lighthearted ditty? A bawdy drinking song?\n\nI could use some help with the lyrics, if you fancy a go at it.\n\nTalk to me and we'll write a song together!", sourceObjective = "Talk to Russell Brower and help him write a song.", progress = "\"Words and Music by Russell Brower the Bard and {name} the {class}.\"\n\nThat's got a ring to it.", completion = "Well, it's catchy, that's for sure.\n\nBut is it a classic?", sourceObjectiveStatus = "unverified-source-field" }
quests[28414] = { id = 28414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fourth and Goal", description = "It's all up to you, kid. You demolished the Steamwheedle Sharks, so now all that's left to do is to kick the winning goal.\n\n<The coach leans in close and whispers in your ear.>\n\nNow, just between you and me, I think we should do this one right. I don't want you to just kick a goal... I want you to kick it so far it sails between the two smokestacks behind the goal!\n\nI've modified the footbomb to give you the extra power that you'll need.\n\nNow get out there and make me proud!", sourceObjective = "Get in the Bilgewater Buccaneer and score the winning goal by kicking the Footbomb through the smokestacks behind the opposing goal.", completion = "Uh... you did it, kid. You REALLY did it! We won the game and....\n\nDID YOU SEE THAT DRAGON?!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[28415] = { id = 28415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SEVEN! YUP!", description = "We have to take action.  Winky and Gor'tesh were fighting, so I planned this friendship ceremony to help the two of them make up.  Everything was going well, until...\n\nWell, you know the rest.\n\nI even bought drinks!\n\nWinky loves flameflies.  He runs off to chase them most every night.  I'm thinking maybe that's where he went.\n\nYou'll find flameflies to the west and north, wherever you find lava.  Bring me seven of them, and hurry!\n\nGor'tesh might leave next!", sourceObjective = "Gather 7 Flameflies.", progress = "<Oralius grasps at the air, lifts his fist, and peers hopefully between his clenched fingers.>", completion = "You'll never guess what happened!  Winky came back!  No flameflies needed.\n\nCan a dwarf get a celebratory belly rub?  Come on now!  RUBBA MAH BELLY!", sourceObjectiveStatus = "unverified-source-field" }
quests[28416] = { id = 28416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Vengeance", description = "{name}... is that you?  I thought you were dead, with the rest of them!\n\nNo, you were always strong, even back then, even in Redridge.\n\nOur fight's not over, {name}.  They already attacked our homeland once.  I'm here to make sure it doesn't happen again.\n\nIf you can still fight like you did back in the day, then join me.  You can start by heading south, to the Whelping Downs, and slaying their whelpers and their hatchling black dragons.\n\nIt'll be like old times.", sourceObjective = "Slay 5 Blackrock Whelpers and 5 Flamescale Broodlings.", completion = "Glad to have you on my side, {name}.  Bravo Company reunited, right?\n\nOh, did I mention that Troteman's here, too?", sourceObjectiveStatus = "unverified-source-field" }
quests[28417] = { id = 28417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Done Nothing Wrong", description = "The Blackrock orcs of the steppes serve a dark master -  one who performs twisted experiments on living creatures to create his own menagerie of abominations.  Many of his test subjects are as corrupted as their master, but others are completely innocent.\n\nIn the whelping downs to the south, they chain baby dragons to the ground, preparing them for such experiments.  I will not stand for this.  Break their fetters and return the hatchlings to me... to safety.", sourceObjective = "Obtain a Freed Red Whelpling, a Freed Green Whelpling, a Freed Blue Whelpling, and a Freed Bronze Whelpling.", progress = "I hope we weren't too late.", completion = "I will see to it that these dragons are taken care of.", sourceObjectiveStatus = "unverified-source-field" }
quests[28418] = { id = 28418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Vengeance", description = "I am a Blackrock orc by birth.  I spent a large part of my youth inside that mountain.\n\n<Ariok motions towards Blackrock Mountain, to the north.>\n\nBut while I share blood with them, I do not share their outlook.  And I am seeking an ally to assist me in stopping their upcoming attack.\n\nSo prove yourself.  Travel south, to the Whelping Downs, and slay their whelpers and the hatchling black dragons.  Prove to me that you're ready for this war.", sourceObjective = "Slay 5 Blackrock Whelpers and 5 Flamescale Broodlings.", completion = "So you're in, then?\n\nGood.", sourceObjectiveStatus = "unverified-source-field" }
quests[28419] = { id = 28419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stocking Up", description = "If we're going to wage war against the Blackrock clan, we're going to need to plan ahead.  My father has already put the plan together - now it's time to execute.\n\nI need scorpid stingers... the sharpest ones you can find.  Scorpids are all over the steppes, but you can find most of them in the gulch to the west.\n\nDon't worry about what they're for.  You'll find out soon enough.", sourceObjective = "Obtain 5 Razor-Sharp Scorpid Barbs.", progress = "Back already?", completion = "Those scorpids are easy to underestimate.  You're lucky you didn't end up on the end of one of these barbs.  Or maybe you're just good.\n\nI'll add these to the stockpile.  We're not done yet, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28420] = { id = 28420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Future Project", description = "According to my father, we'll need worg hides, and lots of them.  It doesn't matter if they're torn, burned, or bloody, but we need plenty of them.\n\nActually, it's probably better if they're a little beat-up.\n\nYou'll find worgs both to the west and to the east of here.", sourceObjective = "Obtain 11 Ember Worg Hides.", progress = "Let's take a look at those hides.", completion = "Believe me, {name}... I'm just as anxious to get to the killing as you are.  We've got to keep to the plan.  The armageddon will come soon enough.\n\nI'll keep these hides here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28421] = { id = 28421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mud Hunter", description = "Hope you're not afraid of getting dirty.  Judging by the looks of you, that won't be a problem.\n\nTo the north, at the lava's edge, you'll find piles of dark mud.  I need it.\n\nIt'd be best if you didn't ask questions, and focused your efforts on following orders, {name}.", sourceObjective = "Obtain 9 piles of Obsidian-Flecked Mud.", progress = "You'll want to watch out for those obsidian elementals.  They have a tendency to sneak up on you.", completion = "This is exactly what we need.\n\nDon't worry, {name}... the killing will come soon enough.", sourceObjectiveStatus = "unverified-source-field" }
quests[28422] = { id = 28422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sand, the Cider, and the Orb", description = "My father is waiting for us to the east.  Before we head out though, we need to gather some more supplies.  This time, you'll be taking it from a warlock by the name of Gorzeeki Wildeyes.\n\nYou'll probably find him to the northwest, near the Altar of Storms.  Tell him he's going to help us out.  We need the sand, the cider, and the orb.\n\nHe'll know what it means.", sourceObjective = "Speak with Gorzeeki Wildeyes near the Altar of Storms.", completion = "Gah!  Who are you?\n\nOh, so Ariok sent you?  Good.  Would ya mind sticking around for a while?  It's nothing big... I just need you to kill some warlocks for me.", sourceObjectiveStatus = "unverified-source-field" }
quests[28423] = { id = 28423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlocks Have the Neatest Stuff", description = "Ariok said he needs supplies?  I've got plenty of supplies!  Problem is, those warlocks have kicked me out of my home, and they're not letting me back in.\n\n<Gorzeeki sizes you up.>\n\nYou might be able to get in, though.  Head north, and grab some of my slumber sand, my fel slider cider, and a clear glass orb.  I'm pretty sure that's what he wants.\n\nOh, and if you happen to accidentally kill any of those orcs while you're up there, I wouldn't be terribly upset.", sourceObjective = "Obtain a handful of Slumber Sand, a jug of Fel Slider Cider, and a Clear Glass Orb.", progress = "Let's see if you managed to get everything.", completion = "I hope that's what Ariok was looking for.  It's not doing me much good right now, anyhow.", sourceObjectiveStatus = "unverified-source-field" }
quests[28424] = { id = 28424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Boxing", description = "Ner'gosh the Shadow is the leader of those warlocks to our north.  He's the jerk that kicked me out of my home once those Blackrock orcs started showing up.  Well, they're all jerks, but he's the jerkiest.\n\nIf I'm ever going to move back in near the Altar, Ner'gosh has to go.", sourceObjective = "Slay Ner'gosh the Shadow.", completion = "Knowing the way those orcs operate, there'll be another one to take his place soon.  I'll see if I can't sneak back into the altar before that happens.\n\nThanks, buddy.", sourceObjectiveStatus = "unverified-source-field" }
quests[28425] = { id = 28425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Ariok", description = "Well I suppose I'm done with you here.  I'll go shoo those other warlocks out when I build up the courage.\n\nHere, don't forget those supplies.", sourceObjective = "Bring the Warlock's Supplies back to Ariok at Flamestar Post in Burning Steppes.", progress = "It looks like you managed to deal with Gorzeeki.", completion = "<Ariok looks through the crate.>\n\nGood, good, good.  We can move on.  Our war takes us east, away from Blackrock Mountain... for now.", sourceObjectiveStatus = "unverified-source-field" }
quests[28426] = { id = 28426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chiselgrip, the Heart of the Steppes", description = "We're headed to Chiselgrip, right in the center of these steppes.  We'll rendezvous with the Thorium Brotherhood there, as well as with my father.\n\nAre you familiar with the Brotherhood?  Those dark iron dwarves have helped me out more than once.  We may need their help again.\n\nWe'll pass through Black Tooth Hovel on our way there.  What do you say we kill a few of the Blackrock while we travel?  I'm getting a little restless here in this camp.", sourceObjective = "Kill any 15 Blackrock troops on your way to Chiselgrip.", completion = "You'll have to excuse me, but we're not taking visitors right now.  I'll ask you to leave Chiselgrip out the same door you came in.\n\nOh, Ariok... is that you?", sourceObjectiveStatus = "unverified-source-field" }
quests[28427] = { id = 28427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Needle in a Hellhole", description = "Lok'tar, {class}.  My name is Eitrigg, of the Argent Crusade... formerly of the Warchief's Honor Guard.  Before that, of the Blackrock orcs.\n\nI trust my son has briefed you on our plan.  He hasn't?  That is probably for the better.\n\nThe next part of the plan is going to require a bit of subtlety.  Speak with Thelaron Direneedle, the tailor here in town.  I've already given him the hides and mud that you've collected.  He's going to need to size you.\n\nThat's right, {race}: you're going undercover.", sourceObjective = "Speak with Thelaron Direneedle at Chiselgrip in Burning Steppes.", completion = "You need a disguise?  Well, you came to the right place, honey.\n\nLet me take a look... mm-hmm.  I know exactly what we'll do.", sourceObjectiveStatus = "unverified-source-field" }
quests[28428] = { id = 28428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as an orc.  Their army is made mostly of orcs, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", sourceObjective = "Bring the appropriate amount of supplies from the Tailoring Table to Thelaron Direneedle at Chiselgrip.", progress = "We're not done yet, you little {class}!", completion = "That's it?  That's your disguise?  I'm feeling less confident about our chances.\n\nBut still confident.", sourceObjectiveStatus = "unverified-source-field" }
quests[28429] = { id = 28429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as an ogre.  The firegut ogres have always worked for the Blackrocks, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", sourceObjective = "Bring the appropriate amount of supplies from the Tailoring Table to Thelaron Direneedle at Chiselgrip.", completion = "That's it?  That's your disguise?  I'm feeling less confident about our chances.\n\nBut still confident.", sourceObjectiveStatus = "unverified-source-field" }
quests[28430] = { id = 28430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as a goblin.  The Blackrocks have been known to hire goblin mercenaries to fill their ranks, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", sourceObjective = "Bring the appropriate amount of supplies from the Tailoring Table to Thelaron Direneedle at Chiselgrip.", completion = "That's it?  That's your disguise?  I'm feeling less confident about our chances.\n\nBut still confident.", sourceObjectiveStatus = "unverified-source-field" }
quests[28431] = { id = 28431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Perfect Costume", description = "Judging by your weight, build, and size, we're going to dress you as a troll.  The Smolderthorn trolls have always worked with the Blackrock orcs, so you'll fit right in.\n\nDo you know much about tailoring?  If not, then consider this your first lesson.  My crafting table over there has all the necessary supplies on it.\n\nGo ahead and grab whatever you think is necessary, then bring it here.  Thelaron will fix you right up.", sourceObjective = "Bring the appropriate amount of supplies from the Tailoring Table to Thelaron Direneedle at Chiselgrip.", completion = "That's it?  That's your disguise?  I'm feeling less confident about our chances.\n\nBut still confident.", sourceObjectiveStatus = "unverified-source-field" }
quests[28432] = { id = 28432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Black Tooth Hovel", description = "Undercover work is all about swagger.  Just act like you're supposed to be there, and you'll be fine.\n\nYour contact inside Black Tooth Hovel will be an orc by the name of Quartermaster Kaoshin.  He does NOT know you're a spy, so try and stay cool.  Do whatever he asks of you.\n\n<Eitrigg presses a small mechanical object into your palm.>\n\nPlace this device in your ear.  I will be in touch to give you any special instructions.\n\nGood luck out there, soldier.", sourceObjective = "Speak with Quartermaster Kaoshin at the Black Tooth Hovel in Burning Steppes.\n\nProvided item:", completion = "Where have you been, grunt?  You're late!  Give me one reason why I shouldn't kill you on the spot!", sourceObjectiveStatus = "unverified-source-field" }
quests[28433] = { id = 28433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grunt Work", description = "Bah!  You're lucky I'm short-handed today.  Otherwise I'd make you my personal whipping <boy/girl> for the week.\n\nThe officers and high-ranking soldiers need their boots polished.  They've left them out in front of their huts.\n\nI want to see my reflection in those boots, grunt!  Get to work!", sourceObjective = "Vigorously polish 7 pairs of Blackrock Boots.", progress = "Oh, you're asking for it now, grunt.", completion = "Hmph.  Good work, grunt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28434] = { id = 28434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strategic Cuts", description = "<You hear a buzzing in your ear.>\n\n{name}?  It's Eitrigg.\n\nWe've just received the final bit of information for your next mission.  There are three marks that we'd like you to take down.  The first is Voodooist Timan, whom you'll find atop the Pillar of Ash.  Worgmistress Othana is in the central worg pens.  Finally, Gorlop is near the lava pools to the south.\n\nYou will find the scorpid barbs you harvested packed along with your belongings.  Use the barbs on the marks when the time is right.", sourceObjective = "Use the Razor-Sharp Scorpid Barb on Voodooist Timan atop the Pillar of Ash, Worgmistress Othana in the worg pens, and Gorlop when he is near the lava pools.", sourceObjectiveStatus = "unverified-source-field" }
quests[28435] = { id = 28435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kodocaller's Horn", description = "Alright, I've got some actual, legitimate, important work for you.  We've got to call the kodos in from the grazing lands to the south.  General Thorg'izog says we'll be moving out into Redridge soon, and I won't be caught with my kodos down.\n\nUse this horn near a kodo.  It will return to the camp when it hears the call.\n\nYou'll want to watch out.  Sometimes the kodos get a little feisty, so you need to knock them around a bit before they listen to you.", sourceObjective = "Use the Horn of the Callers to call 7 Blackrock War Kodos back to camp. If a kodo turns hostile, fight it until it submits.", sourceObjectiveStatus = "unverified-source-field" }
quests[28436] = { id = 28436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Horn For Ourselves", description = "{name}, it's Eitrigg.  I want you to hold onto that horn.  I'm sure we can improvise and find a way to work it into the plan.\n\nI'm more than a little concerned about what Kaoshin said about attacking Redridge.  We knew an attack was imminent, but not this soon!\n\nReturn to me, with the horn.  We will talk again here, in Chiselgrip.  And try not to ruin that disguise.  You're not done with your undercover work yet.", sourceObjective = "Bring the Horn of the Callers back to Eitrigg at Chiselgrip in Burning Steppes.", progress = "Welcome back, soldier.", completion = "True, an attack on Redridge is an attack against the Alliance... but it is also an attack against innocents.\n\nI won't stand for that.  Not as a Crusader.  Not as an orc.\n\nIt's time we taught the Blackrock clan - my old clan - that their raiding days are over.", sourceObjectiveStatus = "unverified-source-field" }
quests[28437] = { id = 28437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Thorg'izog", description = "Kaoshin turned out to be more helpful than I expected, but we're done with him.  It's time you spoke with the General.  I think you're ready.\n\nGeneral Thorg'izog is one of the \"Big Three\" that run the Blackrock forces here in Burning Steppes.  He leads from the Blackrock Stronghold to the northwest.  Put on your disguise and go speak with him.  See if you can earn his trust.  I will be in touch, should I need anything further.", sourceObjective = "Speak with General Thorg'izog.", completion = "More outsiders?  What do you want?", sourceObjectiveStatus = "unverified-source-field" }
quests[28438] = { id = 28438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trial by Magma", description = "I suppose I'll make the most of this situation.  These goblin mercenaries brought this enormous fire elemental to my stronghold as a \"thank you\" for hiring them.  What am I going to do with an elemental here in the steppes?  That's like bringing sand to the beach.\n\nIf you're looking for work, then prove yourself.  Talk to this goblin here, and challenge his elemental to a fight.  The victor earns my respect, and my time.", sourceObjective = "Speak with Wyrtle Spreelthonket and ask him to release Magma Lord Kolob. Then defeat Magma Lord Kolob in battle.", progress = "What's the matter, are you scared?", completion = "I had a feeling you'd be the one returning to me.  I like your style, soldier.", sourceObjectiveStatus = "unverified-source-field" }
quests[28439] = { id = 28439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Am the Law and I Am the Lash", description = "I've been looking for a good, strong soldier like you.  I need someone to keep my troops in line.\n\nOutside the stronghold, you will find orcs, ogres, and trolls preparing for the assault on Redridge.  My sergeants keep them in line, but I'd like you to assist them.\n\nTake this cudgel and discipline a few of my soldiers.  I don't care if they're misbehaving or standing perfectly in line, I want them beaten.  I want them focused, battle-hardened, and obedient.\n\nNow go.", sourceObjective = "Use the Blackrock Cudgel of Discipline on 20 troops in the Fields of Honor. If one of the troops discovers your disguise, cudgel him to death before he can unmask you.", completion = "I have a feeling we'll be hearing about you and your exploits for a long time, soldier.  I look forward to fighting by your side in Redridge.\n\nYou are dismissed.", sourceObjectiveStatus = "unverified-source-field" }
quests[28440] = { id = 28440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abuse of Power", description = "{name}?  Eitrigg here.\n\nIt sounds like you have earned Thorg'izog's trust, and he's assigned you to discipline duty.  This is fortunate.\n\nWe need you to take out his sergeants.  You'll find them on wolfback, outside of the Blackrock Stronghold in the Fields of Honor.  Use that cudgel on them, several times, until they die.  You'll have to act fast, because if they realize you're not one of them, they can unmask you.  Strike quickly and ferociously, {name}.", sourceObjective = "Kill 5 Blackrock Sergeants using the Blackrock Cudgel of Discipline. Defeat them quickly, before they have a chance to unmask you.", sourceObjectiveStatus = "unverified-source-field" }
quests[28441] = { id = 28441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enough Damage For One Day", description = "We do not have any further strategic need for Thorg'izog or the Blackrock ground troops.  We must continue to the next phase of the plan.\n\nWhen you are finished at the stronghold, return to my son and me, here in Chiselgrip.", sourceObjective = "Return to Eitrigg at Chiselgrip.", completion = "Are you alright?\n\nGood.  You were strong out there, {name}.  Strong, and wise.\n\nNow pack up your things.  We're moving out of here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28442] = { id = 28442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flame Crest", description = "Our work here in Chiselgrip is done, mostly thanks to you.  We'll now be moving on to the northeast, to Flame Crest.\n\nFlame Crest is in the cliffs, past the Ruins of Thaurissan.  It should serve as a sufficient base of operations for the final stages of our plan.\n\nOf course, my son Ariok will be joining you on the road.  As will I.", sourceObjective = "Report to Kibler at Flame Crest in Burning Steppes.", completion = "Oh.  Visitors?", sourceObjectiveStatus = "unverified-source-field" }
quests[28443] = { id = 28443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackened Ashes", description = "I need you to do some more gathering before we can go take out the remainder of the Blackrock army.  If we're going to do this, we're going to do it right, and that means being prepared.\n\nI need ash, {name}.  Not just any ash... ash from the greater obsidian elementals that roam the plains to the southeast.  The stuff is deep, deep black, which is what we need for our next disguise.\n\nDon't worry, you've already got a disguise.  This one is for someone... well, someTHING... else.", sourceObjective = "Obtain 9 piles of Obsidian Ash.", progress = "The ashes of the obsidian elementals are particularly dark - exactly what we need for our purposes.", completion = "Yes, these will do.  I will get this packed up for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[28444] = { id = 28444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Latent Demons of the Land", description = "The lava beds nearby - to the south - play host to flamekin, a brand of fire demon that has long roamed the steppes.  Situations are such in the Blackrock army that, if we are careful, we may be able to sneak some of these flamekin behind enemy lines to cause some havoc.\n\nBring me the bodies of several flamekin.  As demons, they are easily resurrected, and then we can use them for our own purposes.", sourceObjective = "Obtain 18 Fallen Flamekin.", progress = "The flamekin are weak, but they travel in packs.  Be cautious.", completion = "To the untrained eye, these will look exactly like imps.\n\nWe just need to get them to that untrained eye.  I'll work on preparing them for delivery.", sourceObjectiveStatus = "unverified-source-field" }
quests[28445] = { id = 28445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Heap of Delicious Worg", description = "We're going to need fresh meat, which means you're going to be hunting worg.  The worg on this side of the steppes should be your target.\n\n<Eitrigg produces a large blade, which he hands to you.>\n\nHunt the giant ember worgs.  Once you've killed them, use this saw to remove the choicest bits of meat from their bodies.  You will find these worgs all over the steppes, but the closest pack rules the land just to our southeast.", sourceObjective = "Use the Worgsaw on the bodies of slain Giant Ember Worgs to obtain 40 Worg Cutlets.", progress = "Any luck out there?", completion = "This meat looks good... but I think it needs a little \"seasoning\".  I'll make sure that gets taken care of.\n\nThank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28446] = { id = 28446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Tour", description = "My legs are getting a little restless again.  You interested in taking a little tour, {name}?\n\nWe're going to take a trip around Dreadmaul Rock.  I'd like to investigate some of the Blackrock army before we make our move, and I figure we might as well kill some of them while we're on the way.", sourceObjective = "Kill 25 Black Dragonspawn or Black Wyrmkin.", completion = "<Ariok is covered in blood and sweat.>\n\nThat was exactly what I needed.", sourceObjectiveStatus = "unverified-source-field" }
quests[28447] = { id = 28447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draconic Vanguard", description = "The Blackrock orcs don't come alone.  You've already seen that they've got the Firegut ogres and Smolderthorn trolls on their side.  Unfortunately for us, they're also teamed up with the black dragonflight.\n\nThe orcs and the dragons have already sent some of their champions to stand guard at rally points, which are marked by a dragon skull on a pike.  You and I are going to find these rally points and take out this vanguard before the battle starts.\n\nReady?", sourceObjective = "Slay Minyoth, Whelptamer Akumi, Terromath the Seared, and Tugnar Goremaw.", completion = "Your kill count is adding up, {name}.  We're chipping away at them.\n\nAnd we are going to win.", sourceObjectiveStatus = "unverified-source-field" }
quests[28448] = { id = 28448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Deal With a Dragon", description = "While we are circling around Dreadmaul Rock, there's one more stop that we need to make.\n\nYou remember the hatchlings that you freed from the Whelping Downs?  I've been watching over them, and now we're going to deliver them to someone who will take care of them better than we can.  He's staying in Slither Rock, to the northeast of Dreadmaul Rock.\n\nHis name is Acride, and he might be the key to victory in the upcoming battle.", sourceObjective = "Deliver the Rescued Whelplings to Acride at Slither Rock in Burning Steppes.", progress = "You've arrived, {name}.", completion = "Yes, the whelplings.  I will take care of them.\n\nAs for the agreement I made with your father earlier, tell him that I will hold up my end of the bargain.  You will have your dragon for the battle against the orcs.\n\nWe share your grudge against the Blackrock clan.", sourceObjectiveStatus = "unverified-source-field" }
quests[28449] = { id = 28449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Placing the Pawns", description = "<You hear a buzzing in your ear.>\n\n{name}.  It sounds like you and Ariok have finished with your tasks.  I've also finished mine.\n\nReturn to Flame Crest.  I've prepared a few packages to deliver to the Big Three: Thorg'izog, Neeralak, and Xi'lun.  You've already met General Thorg'izog.  This will be your chance to meet the other two.\n\nThat is, before you kill them.", sourceObjective = "Return to Eitrigg at Flame Crest in Burning Steppes.", completion = "Good, you're back.\n\nI hope you've still got that disguise.  You're going back undercover, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28450] = { id = 28450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Delivery for Thorg'izog", description = "General Thorg'izog is staying among the ogres in the Firegut Furnace, a cave on the western edge of Dreadmaul Rock.  I'd like you to deliver this to him and the ogres.\n\nInside this package, you will find the worg cutlets you obtained, marinated in the fel slider cider that we took from the Altar of Storms.\n\nI would avoid eating it if I were you.\n\nBring it to General Thorg'izog.  He will make sure that his troops are fed and, with any luck, he will eat some himself.", sourceObjective = "Using your Blackrock Disguise, bring the Slider Cider-Marinated Cutlets to General Thorg'izog at Firegut Furnace in Burning Steppes. Speak with Eitrigg if you need a new Blackrock Disguise.", progress = "What've you got there, soldier?", completion = "Well would you look at that!  My favorite soldier comes through in the clutch!\n\nI'll make sure to get this distributed among the ogres.\n\nI'll see you in Redridge, soldier.  For the glory of the Blackrock!", sourceObjectiveStatus = "unverified-source-field" }
quests[28451] = { id = 28451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Delivery for Neeralak", description = "The warlocks of the Blackrock Clan often practice their magic in the Skull Warren, a cave on the eastern side of Dreadmaul Rock.  Their leader, Xi'lun, is busy elsewhere, so the cave is currently being held by another of the Big Three: Dragon-Lord Neeralak.  And Neeralak's expertise is in dragons, not in necromancy.\n\nI've used the slumber sand on those flamekin you captured.  Try to convince Neeralak that they're warlock imps, and not flamekin.  When they wake up, they won't be happy.", sourceObjective = "Using your Blackrock Disguise, sneak into the Skull Warren and convince Dragon-Lord Neeralak to take your Crate of Sleeping Flamekin. Speak with Eitrigg if you need a new Blackrock Disguise.", progress = "What?", completion = "What are these?  Oh, are these imps?\n\nI'm pretty sure that imps don't just fall asleep in boxes!\n\nI'll take your word for it, though.  I don't understand any of this warlock crap.  Leave them in the corner.", sourceObjectiveStatus = "unverified-source-field" }
quests[28452] = { id = 28452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Delivery for Xi'lun", description = "Intel tells us that High Warlock Xi'lun - the final member of the Big Three - is within the cave atop Dreadmaul Peak, preparing for his big moment.\n\nHe is waiting for a delivery: an Orb of Domination, with which he can perform a powerful summoning ritual.  I want you to give him this:\n\n<Eitrigg hands you a glass orb.>\n\nThis is the clear glass orb that you freed from the Altar of Storms.  It is powerless.  Give it to Xi'lun, and cross your fingers that he doesn't notice.", sourceObjective = "While using the Blackrock Disguise, deliver the Clear Glass Orb to High Warlock Xi'lun atop Dreadmaul Rock in Burning Steppes. Speak with Eitrigg if you need a new Blackrock Disguise.", progress = "I don't have time for games, fool.  Get out of my sight.", completion = "Pff!  You're late!  Do you know how long I've been waiting for Ner'gosh to deliver this orb?\n\n<Xi'lun looks down at the orb, then up at you.>\n\nThere's something strange about this orb... it's too...\n\n<Xi'lun trails off.>\n\nNever mind, it must be my nerves talking.  Thank you for the delivery.  For blood and honor!", sourceObjectiveStatus = "unverified-source-field" }
quests[28453] = { id = 28453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Locked and Loaded", description = "{name}, come in.  Can you read me?\n\nThe battle is about to start.  I hope you've delivered all of those packages.\n\nI need you here in Flame Crest, NOW.", sourceObjective = "Report to Eitrigg at Flame Crest in Burning Steppes.", completion = "{name}'s here!  We can get started.\n\nThis is our big moment, {name}.  I hope you are prepared.", sourceObjectiveStatus = "unverified-source-field" }
quests[28454] = { id = 28454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Dreadmaul Rock", description = "This is it, {name}.  A sad day... but a day in which the Blackrock orcs will learn a powerful lesson.  Today, our plan comes to fruition.\n\nCome with me.  We're going to go talk to Acride and call in that favor that he owes us.  Then we'll stop this invasion of Redridge before it even starts.", sourceObjective = "Slay 200 Blackrock Invaders. If you should lose your vehicle, use the Horn of the Callers to summon it again.", completion = "<Eitrigg looks over the devastation below.>\n\nOur job is almost done, {name}.  It's time to deliver the deathblow.", sourceObjectiveStatus = "unverified-source-field" }
quests[28455] = { id = 28455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glory Amidst Chaos", description = "You and my son are going back to that mountain.  There's three orcs who survived the attack, and we won't rest until they're dead.\n\nThat's right, I'm talking about the Big Three.\n\nGeneral Thorg'izog crawled back into the Firegut Furnace, and Dragon-Lord Neeralak is cowering in the cave on the mountain's peak.  Xi'lun is in the back of the Skull Warren, plotting with his fellow warlocks.\n\nLeave your mark, {name}.  Topple these corrupt Blackrock orcs once and for all.", sourceObjective = "Kill General Thorg'izog, Dragon-Lord Neeralak, and High Warlock Xi'lun.", completion = "<Eitrigg bows.>\n\nWelcome home, boys.", sourceObjectiveStatus = "unverified-source-field" }
quests[28456] = { id = 28456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spoils of War", description = "While the Blackrock orcs still swarm in their spire, I doubt their plans will take them anywhere near the innocent people of Redridge anytime soon.  You and Ariok saw to that.\n\nI'd say we were fairly resourceful here in Burning Steppes - those warlock supplies we collected certainly came in handy, as did the obsidian ash that we used to conceal our dragon.\n\nThere were, however, some collected items left over.  Please, take your pick before you move on, beyond the steppes.", sourceObjective = "Inspect the Box of Left Over Supplies at Flame Crest in Burning Steppes.", completion = "You peer inside, and find...", sourceObjectiveStatus = "unverified-source-field" }
quests[28457] = { id = 28457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dangerous Alliance", description = "The Shattered Hand believes that the Dark Iron dwarves and Twilight's Hammer are working together. There's evidence that they are preparing a joint attack from within Blackrock Mountain. We can't allow such a force to depart Blackrock Mountain.\n\nYou must go into Blackrock Depths and capture the Twilight's Hammer attack plans from General Angerforge in the West Garrison. Eliminate the elementals Twilight's Hammer has provided to support his forces.", sourceObjective = "Kill 6 Fireguard Destroyers and recover the General's Attack Plans from General Angerforge at the West Garrison in Blackrock Depths.", progress = "We cannot afford to allow the Dark Iron dwarves to ally with Twilight's Hammer.", completion = "The warchief will be most interested in seeing these plans. You are a most loyal member of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[28458] = { id = 28458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pyromancer's Grimoire", description = "The power of the Dark Iron forces and their Twilight's Hammer allies is growing within Blackrock Mountain. Pyromancer Loregrain is a powerful and influential magus in the Twilight's Hammer delegation. If we could get our hands on his grimoire, I could develop counters for Twilight's Hammer spells and curses.\n\nYou must descend into Blackrock Depths, locate the Shrine of Thaurissan, and capture the grimoire. Show Loregrain and his Twilight minions no mercy.", sourceObjective = "Kill 6 Twilight Emissaries and recover Loregrain's Grimoire from Pyromancer Loregrain at the Shrine of Thaurissan in Blackrock Depths.", progress = "Have you managed to capture the pyromancer's grimoire?", completion = "<Ureda looks through the grimoire with interest.>\n\nThere's a wealth of arcane knowledge in this book! We will learn much about our enemies and the arcane arts.", sourceObjectiveStatus = "unverified-source-field" }
quests[28459] = { id = 28459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stones of Binding", description = "The Shattered Hand has discovered increased collaboration between Twilight's Hammer and the Dark Iron dwarves in Blackrock Depths. We have an opportunity to strike at our enemies and empower ourselves, {name}.\n\nTwilight's Hammer followers have placed a number of elemental binding stones throughout Shadowforge City, the Domicile, the Shrine of Thaurissan, the West Garrison and the East Garrison. Find and capture those stones!", sourceObjective = "Recover 6 Elemental Binding Stones from Blackrock Depths. You can find the stones in Shadowforge City, the Domicile, the Shrine of Thaurissan, the East Garrison, and the West Garrison.", progress = "Have you managed to find those binding stones?", completion = "The binding stones you brought back are exceedingly powerful. Not only have we dealt a blow to the Horde's enemies, but you have also discovered a fascinating source of power.", sourceObjectiveStatus = "unverified-source-field" }
quests[28460] = { id = 28460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Threat of the Winterfall", description = "I came to Winterspring to investigate the Frostfire Hot Springs. I've noticed that the water seems to have... strange qualities. I haven't yet been able to discover the source, and to tell you the truth, I've had some difficulty lately, due to the Winterfall furbolg.\n\nThey seem to be drawn to the springs, just as I am. They have become extremely protective of the water, and won't let me come near the two larger springs to the north of here.\n\nI'd like to continue my studies, so won't you help me?", sourceObjective = "Slay 15 Winterfall furbolg of any kind near the Frostfire Hot Springs.", completion = "Thanks so much, {name}! Now I can get back to work here.\n\nDid you find anything of interest at the Winterfall camp?", sourceObjectiveStatus = "unverified-source-field" }
quests[28461] = { id = 28461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Golem Lord's Creations", description = "The Shattered Hand has discovered some disturbing information in Blackrock Depths. It appears Twilight's Hammer is working with the Dark Iron engineer, Argelmach, to create war golems powered by elementals. These golems could be a great advantage for our enemies.\n\nIt is your duty to prevent that from happening. Find the Manufactory in Blackrock Depths, capture the blueprints he's using to make those golems, and recover the elemental modules he's using to power them.", sourceObjective = "Obtain 5 Elemental Modules from the golems in the Manufactory of Blackrock Depths and recover the Elemental Golem Blueprints.", progress = "We cannot afford to allow those golems to be used against us.", completion = "Can you imagine what would happen if they got these models working and into the field? You've done a great service for the Horde, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28462] = { id = 28462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterfall Firewater", description = "This vial that you picked up from the Winterfall furbolg is empty, but you can detect a few drops of a strange green liquid inside; it almost glows.\n\nIs it something important?\n\nDonova Snowden would probably be able to tell you more, since she has been camped by the hot springs in Winterspring for some time now.", sourceObjective = "Bring the Empty Firewater Flask to Donova Snowden in Winterspring.", sourceObjectiveStatus = "unverified-source-field" }
quests[28463] = { id = 28463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Iron Army", description = "As a member of the Shattered Hand, you know that it is our job to watch the Horde's enemies. We have discovered that the Dark Iron dwarves and their new allies, Twilight's Hammer, are preparing to attack.\n\nI'm sending you to help deal with this threat before the Dark Iron army marches. Take this poison and apply it to the soldiers' rations of grain in Blackrock Depths.\n\nThe rations for most of the Dark Iron army are kept in the East and West Garrison of Blackrock Depths.", sourceObjective = "Use the Fast-Acting Poison to contaminate 6 Grain Rations in the West Garrison or East Garrison of Blackrock Depths.", completion = "The poison should decimate their ranks if they're slow in discovering the tainted rations. Even if it does not kill most of the troops, we will have delayed them significantly. Well done.", sourceObjectiveStatus = "unverified-source-field" }
quests[28464] = { id = 28464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falling to Corruption", description = "The aggression of the Winterfall furbolg has to have its source somewhere. I'd like to get to the bottom of it if I can!\n\nI've seen the furbolg in the camps to the north brewing something in a cauldron. They seemed very protective of it... if whatever they're cooking up is what's causing this, I must examine it myself.\n\nFind that cauldron if it's still there, and bring me back what's inside!", sourceObjective = "Find the Winterfall Cauldron at the northern Winterfall camp.", completion = "Inside the cauldron bubbles a rotting, repulsive-smelling substance...", sourceObjectiveStatus = "unverified-source-field" }
quests[28465] = { id = 28465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaves of the Firelord", description = "Within the halls of Blackrock Depths, the Twilight's Hammer cult and the Dark Iron dwarves are gathering their forces. Backing up their legions are hordes of fire elementals bound to the service of the firelord, Ragnaros.\n\nIf we can free those elementals from their bonds, we can both weaken our enemies and honor the elements. Take this totem with you and use it on subdued fireguards. It will free their spirits from their bondage and restore them to their natural state.", sourceObjective = "Use the Totem of Freedom to free the essences of 6 Fireguards, Fireguard Destroyers, or Blazing Fireguards in Blackrock Depths.", completion = "Your actions honor the ancestors and the Horde, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28466] = { id = 28466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of Darkness", description = "Blackrock Depths has long been home to our enemies, but now the Shattered Hand has discovered that the Dark Irons and Twilight's Hammer are increasing their collaboration. Using the cult's knowledge, the Dark Iron dwarves are imbuing their weapons with elemental powers. They've outfitted the Anvilrage legion with these fearsome new weapons.\n\nI want you to go into Blackrock Depths and gather the weapons from the Anvilrage dwarves there and break them over the Black Anvil in the heart of Shadowforge City.You will be able to choose one of these rewards:", sourceObjective = "Capture 5 Elemental-Imbued Weapons from Anvilrage dwarves in Blackrock Depths, then break them over the Black Anvil in Shadowforge City.", sourceObjectiveStatus = "unverified-source-field" }
quests[28467] = { id = 28467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystery Goo", description = "The greenish substance inside the cauldron is putrid and viscous.  No matter what it is, it doesn't seem to be good.\n\nIt would be best to report back to Donova with your findings, along with a sample of the liquid in the cauldron.", sourceObjective = "Report back to Donova Snowden with your findings.", progress = "I hope you found something, {name}. The Winterfall are becoming increasingly aggressive!", completion = "Disturbing news indeed. This stuff's much more like what you'd see in Felwood than in Winterspring...", sourceObjectiveStatus = "unverified-source-field" }
quests[28469] = { id = 28469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterfall Runners", description = "Very interesting, {name}...\n\nWhen this toxic substance is mixed with the water from the hot springs, it loses its toxicity, only retaining the ability to temporarily affect those that ingest it. This must be why the Winterfall protect the hot springs so fervently -- they need them to purify their firewater.\n\nWe need to stop this -- cut off contact between the Winterfall and the Deadwood. A group of runners walks the distance between their village and Felwood. Find and defeat them, and steal their shipment.", sourceObjective = "Find and defeat the Winterfall Runner and take the Winterfall Crate from him.", progress = "We'll see what happens when the Winterfall don't get their firewater!", completion = "<Donova examines the contents of the crate.>\n\nI wonder if consuming this substance makes the furbolg more aggressive. They do seem much larger...", sourceObjectiveStatus = "unverified-source-field" }
quests[28470] = { id = 28470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Chief Winterfall", description = "The Winterfall furbolg are not a normally aggressive tribe, and this change in their behavior leads me to think that they must be under orders from their chief. We most likely can't undo the damage that has already been done, but if their leader is slain, they may not get any worse.\n\nHead east again, past where you found that cauldron. High Chief Winterfall is here, at the easternmost part of Timbermaw Post.", sourceObjective = "Slay High Chief Winterfall.", completion = "Thank you so much, {name}. I hope to get back to my studies without worry that I will be ambushed. Please accept this as a reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[28471] = { id = 28471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Piece", description = "The log you found on the high chief looks extensive, but after looking through a couple of the pages, you find that you cannot read the text. The markings are so crude and poorly-formed that you are not sure if anyone would be able to read them.\n\nBut perhaps Donova will be able to tell you what it says...", sourceObjective = "Bring the Crudely-written Log to Donova Snowden in Winterspring.", progress = "Now, what's this, {name}?", completion = "I wonder what all of this means... I can't make anything out...", sourceObjectiveStatus = "unverified-source-field" }
quests[28472] = { id = 28472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words of the High Chief", description = "The Winterfall are no longer a threat to me, but if you still want to find out what was driving the furbolg to create and consume this strange firewater, I think you should seek out Kelek Skykeeper.\n\nHe's a druid that once worked to help cleanse Felwood with the Emerald Circle, and has since come here to study the nearby ruins.\n\nYou might be able to find him to the east at Lake Kel'theril, where he spends his time recently.", sourceObjective = "Take the Crudely-written Log to Kelek Skykeeper at Lake Kel'theril.", progress = "What is it you carry, {class}?", completion = "Yes, if you let me examine this for a while, I might be able to translate it for you.\n\n<Kelek flips through the pages.>\n\nWhen I am able to look over this fully, I will send word to you.\n\nThank you for sharing this with me, {name}. Very little is known about the Winterfall furbolg.", sourceObjectiveStatus = "unverified-source-field" }
quests[28473] = { id = 28473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons of Darkness", description = "Blackrock Depths has long been home to our enemies, but now the Shattered Hand has discovered that the Dark Irons and Twilight's Hammer are increasing their collaboration. Using the cult's knowledge, the Dark Iron dwarves are imbuing their weapons with elemental powers. They've outfitted the Anvilrage legion with these fearsome new weapons.\n\nI want you to go into Blackrock Depths and gather the weapons from the Anvilrage dwarves there and break them over the Black Anvil in the heart of Shadowforge City.", sourceObjective = "Capture 5 Elemental-Imbued Weapons from Anvilrage dwarves in Blackrock Depths, then break them over the Black Anvil in Shadowforge City.", completion = "Your actions honor your brethren and the Horde, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28474] = { id = 28474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Scheming", description = "The influence of Twilight's Hammer grows within Blackrock Depths. They have allied with the Dark Iron dwarves and seek to convince them to strike outside the mountain.\n\nWe must destroy the instruments of the Twilight's Hammer agitation. Their influence over the Dark Irons must be minimized.\n\nI want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", sourceObjective = "Use the Glowing Torch to destroy 8 copies of The Twilight Creed in the Domicile of Blackrock Depths.", completion = "This will not dissuade Twilight's Hammer, but perhaps it will increase the suspicion between them and the Dark Irons.", sourceObjectiveStatus = "unverified-source-field" }
quests[28475] = { id = 28475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Scheming", description = "In Blackrock Depths, Twilight's Hammer has started to persuade the Dark Irons to strengthen their alliance and prepare their armies for a campaign outside the mountain.\n\nWe must not allow this manipulation to create a combined Dark Iron-Twilight's Hammer force! We must destroy the tools of the cult's persuasion.\n\nI want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", sourceObjective = "Use the Glowing Torch to destroy 8 copies of The Twilight Creed in the Domicile of Blackrock Depths.", completion = "We can only hope your efforts will keep the two forces apart long enough for us to exploit their weakness.", sourceObjectiveStatus = "unverified-source-field" }
quests[28476] = { id = 28476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Scheming", description = "In Blackrock Depths, Twilight's Hammer has started to persuade the Dark Irons to strengthen their alliance and wage a campaign of conquest.\n\nWe have to act before the cultists can whip up the bloodlust in the Dark Irons and their leadership. Perhaps the best way to deal with this is to destroy the material the cultists are distributing to the dwarves.\n\nI want you to go into Domicile portion of Blackrock Depths and use this torch to burn the books that the Twilight's Hammer is distributing there.", sourceObjective = "Use the Glowing Torch to destroy 8 copies of The Twilight Creed in the Domicile of Blackrock Depths.", sourceObjectiveStatus = "unverified-source-field" }
quests[28477] = { id = 28477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Scheming", description = "Our enemies be plottin' against us in the halls of Blackrock Depths. The Twilight's Hammer cultists, they be busy preaching and handin' out books to the Dark Irons, tellin' them that it's time for war. Wit' a Dark Iron army at their backs, the Twilight's Hammer be a formidable force. We must put an end to the agitation!\n\nI be wantin' you to go into Domicile of Blackrock Depths and use this torch to burn those Twilight's Hammer books!", sourceObjective = "Use the Glowing Torch to destroy 8 copies of The Twilight Creed in the Domicile of Blackrock Depths.", sourceObjectiveStatus = "unverified-source-field" }
quests[28478] = { id = 28478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Scheming", description = "It wasn't enough for their master to break the world, no! Twilight's Hammer is doing its best to unite our enemies against us, particularly in Blackrock Depths. They've got a whole team of emissaries down there spreading propaganda aimed at starting a joint campaign.\n\nI've always heard that the medium's the message. Well, it's time to destroy the message!\n\nI want you to go into the Domicile of Blackrock Depths and use this torch to burn those Twilight's Hammer books!", sourceObjective = "Use the Glowing Torch to destroy 8 copies of The Twilight Creed in the Domicile of Blackrock Depths.", sourceObjectiveStatus = "unverified-source-field" }
quests[28479] = { id = 28479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Kel'Theril", description = "At this lake, the Crystal of Zin-Malor was stolen by the Highborne. The crystal was a powerful artifact that bent arcane magic in wild and unpredictable ways... but it could only be held by the worthy, and brought doom upon all others.\n\nThe spirits that wander here span generations, each shackled here by Zin-Malor. Some will speak and tell their fates.\n\nShould you wish to learn the fate of Zin-Malor, seek the spirit at the center of the lake...", sourceObjective = "Speak with the Kaldorei Spirit at Lake Kel'theril in Winterspring.", completion = "Pity me, stranger, and all the Highborne, for it was here our folly began... our folly that cursed our children, and our children's children, to this day.", sourceObjectiveStatus = "unverified-source-field" }
quests[28480] = { id = 28480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieutenants of Darkness", description = "The armies of Ramkahen are getting obliterated by Neferset's immortal guardians.\n\nThe only way to defeat them is to slay the Dark Pharaoh of Neferset.\n\nBefore we make our move, however, we're going to need to take care of his lieutenants.\n\nGo behind the battle-lines and slay Scorpion-Lord Namkhare and High Priest Sekhemet.  Only then will we be ready to confront the Dark Pharaoh himself.", sourceObjective = "Slay Scorpion-Lord Namkhare and High Priest Sekhemet.", progress = "You've returned, {name}.", completion = "You are a valuable ally, {name}.  We are one step closer to defeating the enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[28482] = { id = 28482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sullah's Gift", description = "Jonesy tells me you two need to make it up that mountain.\n\nWell, you're not going far with those troopers crawling all over it like ants on a carcass.\n\nSome of my friends were able to confiscate a bit of the enemy's hardware. It should make your journey a bit easier.\n\nMake your way up the ridgeline to the north, and you'll find it waiting for you.\n\nGood luck, you two!", sourceObjective = "Speak to Harrison Jones at Pilgrim's Precipice.", completion = "Glad you could make it, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28483] = { id = 28483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleeding the Enemy", description = "I will not lie to you, {name}.  We face a tremendous challenge ahead of us.\n\nAs you go behind the enemy lines into Neferset City, I want you to bring back the insignia of any Neferset scum you defeat.\n\nIt will be a boon to our armies to know that you've dealt a crushing blow to the enemy.", sourceObjective = "Obtain 10 Neferset Insignia.", progress = "It is good to see you once more, {name}.", completion = "Excellent job, {name}.  Our troops will hear of your deeds.", sourceObjectiveStatus = "unverified-source-field" }
quests[28484] = { id = 28484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Matter", description = "The magus has been idle for far too long and an idle magus often leads to poorly thought out schemes. This time I am charged with collecting various beast organs in order to power some type of control rod. I am far too frail to go out hunting beasts - especially yetis!\n\nPerhaps if I were to offer you a reward of some kind you would do it? All I need is for you to head west to the yeti caves and kill yetis. Rip their still beating hearts from their chests and bring them back here.", sourceObjective = "Collect 12 Beating Yeti Hearts.", progress = "Bring me yeti hearts, {name}.", completion = "I... um... well... turns out he doesn't need the hearts anymore. Sorry about that! Hope it wasn't too inconvenient! A deal's a deal though, so here is your reward. You can go ahead and keep the yeti hearts. I hear they hold excellent nutritional value - if you're into eating.", sourceObjectiveStatus = "unverified-source-field" }
quests[28485] = { id = 28485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yetimus the Yeti Lord", description = "For years the mountain yeti of this region have been allowed free reign. Our complacency in dealing with the yeti menace has resulted in an aberration! Yetimus, lord of all yetis, has grown to a size and strength that our guard simply cannot handle. We fear that should his appetite lead him near Tarren Mill he would devour us all.\n\nGather a party of suitable adventurers and dispatch the beast. He roams the countryside to the west.\n\nBring me one of his horns and I will reward you handsomely.", sourceObjective = "Take Yetimus' Twisted Horn.", progress = "Yetimus must die!", completion = "So it's true, you did kill the beast! The people of Hillsbrad are indebted to you, {name}. You have made the land safer for our citizens.\n\nTake whatever you may desire from our coffers.", sourceObjectiveStatus = "unverified-source-field" }
quests[28486] = { id = 28486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salhet's Gambit", description = "Neferset City is too well defended.  The mountain next to it, however, is not.\n\nI've spoken to the ranger captain and he's willing to take a handful of his men and secure the strategic mountaintop.\n\nThere is one catch, {name}.  He agreed, but only if you would spearhead the attack with them.\n\nIt must be a small group, else we'll draw the enemy's attention too soon, but trust me... the rangers of Ramkahen are as tough as they come.  With you by their side we'll surely succeed.", sourceObjective = "Escort the Ramkahen Ranger Captain to higher ground.", progress = "Hail, {name}!", completion = "You did it, {name}!  Excellent!", sourceObjectiveStatus = "unverified-source-field" }
quests[28487] = { id = 28487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Humbert's Personal Problems", description = "So this is pretty embarrassing. Where to begin?\n\nWell, you see, Melisara sent me to investigate the yeti menace in the nearby caves, west of here. It was getting late and my armor was weighing heavily on me. I took my gear off and decided to take a stroll. Yes, I, erm, went for a walk. Anyway, when I returned I discovered that my gear had been stolen! It was the yetis. I'm sure of it. They took my pants, sword and helm and ran off into their cave. Get them back for me and I will reward you.", sourceObjective = "Recover Humbert's Sword, Humbert's Helm, and Humbert's Pants.", progress = "I'm practically naked here, {name}. Help me out, eh?", completion = "Thank you, {name}! I promise you that this is the last time I take this gear off.", sourceObjectiveStatus = "unverified-source-field" }
quests[28488] = { id = 28488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beneath the Surface", description = "Among the other precious gemstones hidden deep out of our reach in the Crumbling Depths, there are enormous ruby crystal clusters. They are infused with terrible energy.\n\nIt will not be easy to obtain such a thing, for they are well guarded. But you, you are stubborn and brave. I think this is something you can do.\n\nWithin the Crumbling Depths, look to where the tunnels end abruptly in stone. The clusters are found in those passages when they are to be found at all. Should you find one, return to me.", sourceObjective = "Recover an Enormous Ruby Crystal Cluster.", progress = "These crystals are of great value, particularly to Gorsik. I shall have a heavy sway over him if I come into possession of one. I wish this to be so.", completion = "This is exactly what I was seeking. Thank you, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28489] = { id = 28489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stagwiches", description = "Ever had a stagwich? Me neither. Apparently they're delicious. Now I'm not one for eating, but I am a businessman. If my customers want stagwiches, who am I to argue?\n\nYou're probably asking yourself, \"What does this have to do with me?\" I'll tell you what, {class}, I need stag meat! You get me stag meat from the hill stags of Hillsbrad and I will pay you. Sounds like a pretty good deal, doesn't it?\n\nGet going! Stags are most plentiful to the west.", sourceObjective = "Retrieve 8 slabs of Stag Meat.", progress = "I need stag meat!", completion = "That's a hefty load you're carrying. It should keep my customers satisfied for the time being.\n\nHere is your pay, as promised.", sourceObjectiveStatus = "unverified-source-field" }
quests[28490] = { id = 28490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Darkshore!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Priestess Dentaria at Lor'danel in Darkshore.\n\nThe people of Lor'danel need your aid in caring for the survivors of Auberdine's destruction and securing their town against Twilight's Hammer. Speak to Vesprystus, the hippograph master at Rut'theran Village outside of Darnassus and he'll arrange a flight to Darkshore.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Priestess Dentaria at Lor'danel in Darkshore.", completion = "So, the king has heard our plea? Thank Elune! We can use all the help we can get.", sourceObjectiveStatus = "unverified-source-field" }
quests[28491] = { id = 28491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Fireflies, Flameflies", description = "Most of my fellow residents here at Flame Crest seem to have left at some point.  I guess the Burning Steppes weren't INTERESTING enough for them.\n\nNot me, though.  I'm always finding new reasons to not leave, and the latest happens to be the flameflies that have been appearing lately.\n\nThey appear near lava during the day.  By night, you'll find them almost anywhere.\n\nIf you wouldn't mind collecting some, I might be able to make it worth your while.", sourceObjective = "Gather 7 Flameflies.", progress = "Well?", completion = "Nice work!  More pets for Kibler!", sourceObjectiveStatus = "unverified-source-field" }
quests[28492] = { id = 28492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Ashenvale!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Sentinel Shyela at Orendil's Retreat in northwestern Ashenvale.\n\nThe Horde's aggression in Ashenvale cannot be allowed to stand! Your help is needed to repel the invaders and restore the sacred forest. Head south through the Twilight Vale in Darkshore to reach the forest of Ashenvale.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Sentinel Shyela at Ordanil's Retreat in northwestern Ashenvale.", completion = "Have you come to help us fight back against the forces of the Horde? Every blade and spell will be needed!", sourceObjectiveStatus = "unverified-source-field" }
quests[28493] = { id = 28493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Ashenvale!", description = "All able bodied members of the Horde are hereby ordered to report to Kadrak at the Mor'shan Rampart on the border between the Northern Barrens and Ashenvale. Aid in driving the night elves from the forest, so that we may claim its resources for our people!\n\nTo reach the Mor'shan Rampart, you must take the Gold Road north from Crossroads in the Northern Barrens.\n\nDestiny calls!", sourceObjective = "Report to Kadrak at the Mor'shan Rampart on the border between the Northern Barrens and Ashenvale.", completion = "So you're the reinforcements? I suppose you'll do fine as long you can kill night elves.", sourceObjectiveStatus = "unverified-source-field" }
quests[28494] = { id = 28494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Northern Barrens!", description = "All able-bodied members of the Horde are hereby ordered to report to Kargal Battlescar at Far Watch Post in the Northern Barrens.\n\nYour help is needed to secure the Northern Barrens against the encroaching quilboars and centaurs.\n\nTo reach Far Watch Post, travel west across Durotar's Southfury Watershed and cross the bridge into the Northern Barrens.\n\nDestiny calls!", sourceObjective = "Report to Kargal Battlescar at Far Watch Post in the Northern Barrens.", completion = "You look competent with a weapon or a spellbook. We could use your help in driving back the quilboars in these parts.", sourceObjectiveStatus = "unverified-source-field" }
quests[28495] = { id = 28495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fighting Chance", description = "Blessed be the Light! I need your help!\n\nOn my way into Hillsbrad I noticed several families of adorable little deer. As I went out to pet one of the little fawns a ravenous mountain cat leapt out and killed it. I fled to Tarren Mill and swore to solve the plight of the hill fawn. Now, after many days of tinkering, I have created the hill fawn's salvation!\n\nTake my wand into the fields to the west and use it to empower the wee hill fawns. Once empowered they will be able to fend for themselves!", sourceObjective = "Save 10 Hill Fawns.", completion = "WHAT!? No, don't tell me that, {name}! It can't be true! My... I... I would never...\n\nI won't give up, {class}. Just you wait and see. I will save those fawns!", sourceObjectiveStatus = "unverified-source-field" }
quests[28496] = { id = 28496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Azshara!", description = "All able-bodied members of the Horde are hereby ordered to report to Ag'tor Bloodfist at the Orgrimmar Rear Gate in Azshara.\n\nAid in driving back the encroaching Alliance forces and assist in securing Azshara for the glory of the Horde!\n\nDepart Orgrimmar through its northern gate to reach the Orgrimmar Rear Gate in Azshara.\n\nDestiny calls!", sourceObjective = "Report to Labor Captain Grabbit at the Orgrimmar Rear Gate in Azshara.", completion = "We could sure use some help out here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28497] = { id = 28497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire From the Sky", description = "Sullah wasn't kidding. That hill is crawling with troopers!\n\nJump on and paint our targets for me.\n\nMake every shot count, {name}! We need to be able to get up there.", sourceObjective = "Kill 100 Schnottz Troopers while mounted on the Confiscated Artillery.", completion = "Good work, {name}.\n\nNow let's see if we can make our way up there before they're able to recover.", sourceObjectiveStatus = "unverified-source-field" }
quests[28498] = { id = 28498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Secret of Nahom", description = "There is an old story about Nahom.  It speaks of how a powerful prophet named Atulhet held off troves of enemies by channeling the power of the sun through this very temple.\n\nMost believe the tale to be just a legend, but that power... would certainly be useful to us now.\n\nThe vile Neferset have ransacked Atulhet's tomb.  They've taken any artifacts of power and shattered the tablets that encode his memories.\n\nGo to the Tombs of the Precursors to the east and retrieve any fragments that you find.", sourceObjective = "Obtain 8 Atulhet's Record Fragments.", progress = "Did you find them, {name}?  Were they salvageable?", completion = "Excellent.  Let's see if we can find anything of importance.", sourceObjectiveStatus = "unverified-source-field" }
quests[28499] = { id = 28499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Punish the Trespassers", description = "We, priests of Nahom, are guardians of the Tombs of the Precursors.\n\nEver since the Neferset turned to their new masters, they've turned to great heresies.\n\nThey rob the sacred tombs of our forefathers, seeking powerful artifacts and destroying invaluable relics in the process.\n\nGo to the tombs, east of here and punish the tomb-robbers for their transgressions, lest they join their brethren when the Neferset attack on Nahom begins.", sourceObjective = "Slay any 10 Neferset intruders at the Tombs of the Precursors.", progress = "You're back, {name}.  Is your prowess as great as I've heard?", completion = "Perhaps you are as powerful as I've heard afterall.\n\nYou have our gratitude.", sourceObjectiveStatus = "unverified-source-field" }
quests[28500] = { id = 28500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cypher of Keset", description = "<Salhet spends some time going over the tablets with the priests around him.>\n\nIt's all right here, {name}.  Atulhet built a potent weapon into this temple and the only way to access it is with the correct cypher.\n\nIt is reportedly hidden in the Keset Pass.  We must hope the Neferset looters haven't gotten to it yet.  That's where Raider Lord Havat is operating and he's the most ruthless of the lot.\n\nBut without reinforcements, this might be our only hope for defending Nahom.", sourceObjective = "Obtain the Cypher of Keset.", progress = "Did you retrieve the codex, {name}?", completion = "It is true then?  It does exist!", sourceObjectiveStatus = "unverified-source-field" }
quests[28501] = { id = 28501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defense of Nahom", description = "The enemy is coming... and in great numbers.\n\nWe will get no further reinforcements.  Let us hope we can stop the Neferset advance.\n\nIf Nahom falls, Ramkahen will follow.\n\nGo outside and speak to one of my sergeants when you're ready.  I will help you command the forces we have to the best of my ability.", sourceObjective = "Speak to a Ramkahen Sergeant and succeed in the Defense of Nahom.", completion = "We did it, {name}!  We held Nahom.", sourceObjectiveStatus = "unverified-source-field" }
quests[28502] = { id = 28502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bandit Warlord", description = "Our law demands that those behind this attack face proper retribution.\n\nThe band of bandits' ringleader is a man known as Warlord Ihsenn.\n\nYou will find him in the far west of the desert.  Make sure his transgressions do not go unpunished.", sourceObjective = "Slay Warlord Ihsenn.", progress = "You've returned, {name}.", completion = "I thank you, {name}.  These savages must be punished for what they've done here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28503] = { id = 28503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Thousand Needles!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Caryssia Moonhunter at New Thalanaar at the border between Feralas and Thousand Needles.\n\nThe sentinels need your help to turn back the marauding Grimtotem raiders who dominate the area. To reach New Thalaanar, travel to eastern Feralas, near the border with Thousand Needles.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Caryssia Moonhunter at New Thalanaar on the border between Feralas and Thousand Needles.", completion = "You've arrived just in time, {class}. We need your help to hold off the Grimtotem.", sourceObjectiveStatus = "unverified-source-field" }
quests[28504] = { id = 28504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Thousand Needles!", description = "All able bodied members of the Horde are hereby ordered to report to Nyse at Mudsprocket. Join the Horde forces fighting against the renegade Grimtotems who dominate the area.\n\nNyse will provide you with transportation to the front lines. She will be waiting for you at Mudsprocket's inn, tucked away in southern Dustwallow Marsh.\n\nDestiny calls!", sourceObjective = "Report to Nyse at Mudsprocket in southern Dustwallow Marsh.", completion = "The Horde forces in Thousand Needles desperately need your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[28505] = { id = 28505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Andorhal", description = "I just got word, <lad/lass>.  It doesn't sound good.\n\nThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  King Wrynn has rolled the dice and sent a death knight to lead the charge for his cause, but I'm sure he can use all the help he can get.\n\nI hate to see you go, but they've asked for you by name, {name}.  Speak with Guthrum Thunderfist outside.  He'll put you on the first gryphon out to Andorhal.", sourceObjective = "Speak with Guthrum Thunderfist to fly to Andorhal in Western Plaguelands. Then report to Thassarian within Andorhal.", completion = "It's about time you arrived, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28506] = { id = 28506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "March of the Stormpike", description = "These plans you recovered weave an interesting tale, {name}. The Stormpike have been moving their armies from Alterac Valley into the \"four fingers\" of Hillsbrad for over a month. Somehow they have managed to secretly get their installations set up without our forces knowing. Had we not received these plans they would have marched on us in a week's time, annihilating everything in their path.\n\nWith these plans, though, we can turn the tables.\n\nThis is what we must do...", sourceObjective = "See the March of the Stormpike.", completion = "The time to act is now. The Stormpike must be crushed!", sourceObjectiveStatus = "unverified-source-field" }
quests[28507] = { id = 28507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Tanaris!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Kelsey Steelspark in Gadgetzan.\n\nThe Alliance needs your help to win concessions from the local baron and access to the area's priceless resources. You can reach Gadgetzan by traveling south from the Shimmering Deep in Thousand Needles.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Kelsey Steelspark at Gadgetzan in Tanaris.", completion = "We have to persuade the goblins of Gadgetzan to side with us, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28508] = { id = 28508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Andorhal", description = "I just received the most curious missive.  Curious indeed...\n\nThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  It sounds like Sylvanas has made her move, and to make matters interesting, she's put Koltira Deathweaver, the death knight, in command.\n\nThey've asked for you by name, {name}.  Speak with Kellen Kuhn, the bat handler.  He'll put you on the first bat out to Andorhal.", sourceObjective = "Speak with Kellen Kuhn to fly to Andorhal in Western Plaguelands. Then report to Koltira Deathweaver within Andorhal.", completion = "It's about time you arrived, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28509] = { id = 28509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Tanaris!", description = "All able bodied members of the Horde are hereby ordered to report to Megs Dreadshredder in Gadgetzan. Help the Horde and the Bilgewater Cartel establish a presence in Tanaris before the Alliance does!\n\nYou can reach Gadgetzan in Tanaris by traveling south to the shore from Fizzle and Pozzik's Speedbarge in southeastern Thousand Needles.\n\nDestiny calls!", sourceObjective = "Report to Megs Dreadshredder at Gadgetzan in Tanaris.", completion = "I could use your help, {class}. That blasted gnome is trying to persuade the Steemwheedle Cartel to favor her side!", sourceObjectiveStatus = "unverified-source-field" }
quests[28510] = { id = 28510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Feralas!", description = "All able bodied members of the Horde are hereby ordered to report to Konu Runetotem at Camp Ataya in Feralas. Help the Horde secure the great forest against the Alliance and the Grimtotems.\n\nYou can reach Camp Ataya by traveling south from Desolace and into Feralas.\n\nDestiny calls!", sourceObjective = "Report to Konu Runetotem at Camp Ataya in Feralas.", completion = "There is much wrong in Feralas. I am glad to have your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[28511] = { id = 28511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Feralas!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Telaron Windflight at Dreamer's Rest in Feralas.\n\nThe Alliance needs your help to overcome our enemies, the Horde and the Grimtotems. You can reach Dreamer's Rest by traveling south from Desolace into Feralas.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Telaron Windflight at Dreamer's Rest in Feralas.", completion = "Elune has favored us with your arrival, {class}. There is much to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[28512] = { id = 28512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Aid of the Thorium Brotherhood", description = "Dark Iron dwarves may be scheming and mischievous... but they're not all enemies.  I've spoken several times with the dwarves of the Thorium Brotherhood, and they've never been anything but helpful.\n\nAn acquaintance of mine, Jack Rockleg, came to town not long ago, asking if I could join him on an expedition of some sort.  It sounded important.\n\nI'm a little busy, but maybe you wouldn't mind going?  Just travel west, on the road to Searing Gorge.  You'll see him soon after leaving the Badlands.", sourceObjective = "Speak with Jack Rockleg at Thorium Advance in Searing Gorge.", completion = "Well whadda we have here?  You here to help?", sourceObjectiveStatus = "unverified-source-field" }
quests[28513] = { id = 28513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pride of the Highborne", description = "Ten thousand years ago...\n\nThe Highborne lived here in prosperity. We considered ourselves above the common ranks of the other night elves. With our every need met by magic and wealth, we led lives of indulgence and amusement. And greed...\n\nThe spirits you see here are overwhelmed with remorse and regret. Their anguish chains them here. If you wish to learn more of Kel'theril and Zin'malor, free them from their agony.", sourceObjective = "Slay 8 Anguished or Suffering Highborne.", progress = "Death is not always a relief.", completion = "The Crystal of Zin-Malor was stolen from a far-off temple without remorse. Its ability to control the arcane was too tempting, and when it was toyed with, its shattering cursed us all. Kel'theril suffered until the Sundering destroyed it for good.\n\nThe curse of Zin-Malor binds all who seek its power here. I was the first to fall to its temptation. Thousands of years later, our long lost descendants would be next...", sourceObjectiveStatus = "unverified-source-field" }
quests[28514] = { id = 28514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mouton Flamestar", description = "I get precious little time away from Searing Gorge these days.  I've been meaning to visit a friend in Burning Steppes for the last several months, but haven't had the chance.\n\nHis name is Mouton Flamestar.  While he's not a member of the Brotherhood, he's a trusted friend, and definitely trustworthy.\n\nWill you send him my regards?  You'll have to travel south, through the base of Blackrock Mountain.  Just keep heading south... you'll find him.\n\nThank you.", sourceObjective = "Report to Mouton Flamestar at Flamestar Post in Burning Steppes.", completion = "Oh, Oilfist sent you?  Hah!\n\nDid he ever tell you how he got the name Oilfist?  You'll have to ask him about that one sometime.", sourceObjectiveStatus = "unverified-source-field" }
quests[28515] = { id = 28515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mouton Flamestar", description = "I get precious little time away from Searing Gorge these days.  I've been meaning to visit a friend in Burning Steppes for the last several months, but haven't had the chance.\n\nHis name is Mouton Flamestar.  While he's not a member of the Brotherhood, he's a trusted friend, and definitely trustworthy.\n\nWill you send him my regards?  You'll have to travel south, through the base of Blackrock Mountain.  Just keep heading south... you'll find him.\n\nThank you.", sourceObjective = "Report to Mouton Flamestar at Flamestar Post in Burning Steppes.", completion = "Oh, Oilfist sent you?  Hah!\n\nDid he ever tell you how he got the name Oilfist?  You'll have to ask him about that one sometime.", sourceObjectiveStatus = "unverified-source-field" }
quests[28516] = { id = 28516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Centuries of Suffering", description = "I only agreed to even consider cooperating with night elves and the alliance on rumors that the Crystal of Zin-Malor was found here.\n\nThe crystal is a powerful and ancient artifact, whose destruction cursed this land, and whose reassembly has caused little relief.\n\nBut I cannot face the hauntings that dwell here. Mock me if you must, but if you do, try your own hand. Perhaps the placid spirits that sit at the center of the lake will speak with you...", sourceObjective = "Speak with the Kaldorei Spirit at the center of Lake Kel'theril.", sourceObjectiveStatus = "unverified-source-field" }
quests[28517] = { id = 28517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Howling Oak", description = "So this is it... our new home. I'm not sure if I'll ever feel like I truly have a home again.\n\nWe mustn't be unappreciative of what the night elves have offered us though. Their race is not one to throw out idle welcomes to just anyone. It is a true testament to faith and generosity that they've taken us in.\n\nGwen and Greymane are in the city proper, at the Howling Oak. You should stop by. Take the portal beneath the tree north of us, then seek out the Howling Oak in the northern portion of the city.", sourceObjective = "Speak to Genn Greymane at the Howling Oak in Darnassus.", completion = "This oak was grown through the aid of the druids from a seed taken back on Gilneas. It stands for all that we've endured, and all that we've accomplished.\n\nMay it serve to remind us that our curse is also our blessing.", sourceObjectiveStatus = "unverified-source-field" }
quests[28518] = { id = 28518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy of the High Elves", description = "One hundred years ago...\n\nI and a small group of other High Elves traveled here from our homeland, Quel'thalas. We sought the ancient mysteries of Kel'thoril... to find why it was destroyed.\n\nWe found fragments in the ice, shards of the crystal. The Archmage we accompanied did not take long to fall under their sway. In our foolishness, we noticed too late.\n\nHis spirit wanders in the southeast, among those he drove to madness, still clutching the memory of the precious shard...", sourceObjective = "Obtain the Memory of Zin-Malor from the spirit of Archmage Maenius.", progress = "Maenius was a powerful mage and an honorable elf.  His spirit did not deserve such an ignoble fate.", completion = "We were shocked before we died. Shocked that one among our noble and austere kind could descend into vicious obsession so quickly. We died as naive fools, the victims of our own blithe assumptions.\n\nThe living would know that these events would play out yet again... both here, and among the entire elven race with the fall of Quel'thalas.", sourceObjectiveStatus = "unverified-source-field" }
quests[28519] = { id = 28519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pain of the Blood Elves", description = "One year ago...\n\nThe legend of the Crystal of Zin-Malor reached Silvermoon, and I led a group of the finest warriors and scholars available to this land. We brought ample mana crystals, so none of us would be tempted to taste the crystal itself.\n\nThe crystal did not need our hunger to ruin us. Once in our possession, it warped all but me into wretched beasts.\n\nThe wretched souls still wander, seeking more lives to chain to this lake. Will you give them mercy... or flee to die on safer ground someday?", sourceObjective = "Slay 7 Wretched Spirits or Wretched Spectres at Lake Kel'theril.", progress = "Do not loiter too long. There are few escapes from Kel'theril.", completion = "The living farstrider who sent you here could not bear to see our fate. He ran... a wise decision.\n\nIf one now holds the Crystal of Zin-Malor again, it will spell the doom of all around them. It should never have been reassembled.", sourceObjectiveStatus = "unverified-source-field" }
quests[28520] = { id = 28520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fall of Neferset City", description = "We are ready to strike now, {name}.\n\nIf we take down Dark Pharaoh Tekahn, the immortal colossi will fall and our armies will be able to march into Neferset City.\n\nSeek him out and engage him without fear.  I will make sure you're not alone when it's time to bring him down.", sourceObjective = "Slay Dark Pharaoh Tekahn at Neferset City in Uldum.", completion = "It is done.  We have defeated the Neferset inside their own city.\n\nI wish I could say that there is peace for my people at last, but I only foresee more bloodshed.", sourceObjectiveStatus = "unverified-source-field" }
quests[28521] = { id = 28521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak to Salfa", description = "The threat of corruption comes not only from the Deadwood furbolgs to the south, but also from the east and the Winterfall furbolgs of Winterspring.  If you wish to further aid us, speak with Salfa on the other side of the Hold, by the Winterspring entrance.  Follow the path to the left to reach it.", sourceObjective = "Travel through Timbermaw Hold and exit into Winterspring. Speak with Salfa, who stands guard outside the entrance to Timbermaw Hold.", completion = "Greetings, {class} - I stand guard here as both a speaker for the Timbermaw here in Winterspring and as a defender of the tribe.\n\nOur Winterfall brethren here in this frigid land have fallen under the same corruptive sway as the furbolg of Felwood.  If you've come here offering the Timbermaw furbolgs aid, then we are ready to accept such an offer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28522] = { id = 28522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterfall Activity", description = "The Timbermaw tend to stay to themselves, {name}.  While we do allow safe passage to those we trust, we try to avoid other furbolg tribes if at all possible.\n\nThe Winterfall tribe has become increasingly hostile towards us.  They seem to be in a state of rage, completely engulfed by their own fear and hatred of anything they do not understand.\n\nThe Winterfall carry spirit beads, which have clearly failed to protect them against corruption. Bring me 10 of these beads to show you have thinned their ranks.", sourceObjective = "Collect 10 Spirit Beads from Winterfall furbolg.", progress = "We very much appreciate what you have done for the Timbermaw, {name}.  Your continued efforts will surely earn my tribe's trust and respect.", completion = "Thank you for what you have done, as saddening as it is.  Accept this as a token of thanks.\n\nI would ask of you to please continue helping us, {name}.  We have very few allies on which to call upon, and without your aid, the threats against my tribe would surely be too much for us to handle alone.", sourceObjectiveStatus = "unverified-source-field" }
quests[28523] = { id = 28523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Beads for Salfa", progress = "You've certainly earned my trust, {name}, but you may need to continue to earn the trust of my untrusting tribe.  There is something you can do to earn that trust.\n\nThe Winterfall are known to carry spirit beads to ward against foul spirits.  These beads have clearly failed in their purpose, as the Winterfall themselves are the agents of corruption.  Bring to me these spirit beads from fallen Winterfall furbolgs; for every set of five you bring me, you will earn recognition amongst the Timbermaw.", completion = "Once again, you prove your honor to us!  I will make sure that your deeds are known amongst my kind.\n\nRemember to bring any of the Winterfall's beads you find to me.  For each set you continue to bring to me, I will speak on your behalf to the tribe." }
quests[28524] = { id = 28524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery for Donova", description = "Donova Snowden is a kind dwarf who frequents the nearby hot springs. She claims to be studying their magical properties.\n\nShe is a kind person and has good relations with our tribe. As the Winterfall have become more and more aggressive, she has begun researching the cause of their corruption.\n\nI must keep my post here, but I have made a basket of refreshments for her. Please take it to her for me and tell her we await her next visit.", sourceObjective = "Deliver Salfa's Basket to Donova Snowden in Winterspring.", progress = "Welcome to the hot springs. What've you got there?", completion = "Oh, how nice of those dear furbolg. I feel so bad for them, cooped up in that hold, afraid of the world.\n\nBut can you blame them? These Winterfall furbolg are turning just as vicious as any in Felwood. I'd like to put a stop to it... if only for the sake of my own research, let alone the dear Timbermaw.", sourceObjectiveStatus = "unverified-source-field" }
quests[28525] = { id = 28525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Un'Goro Crater!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Williden Marshal at Marshal's Stand.\n\nThe Alliance needs you to provide support to the Marshal Expeditions as they uncover the secrets of Un'Goro Crater's ancient beasts, unique flora, and powerful crystals. You can reach the crater by departing western Tanaris and following the road all the way to Marshal's Stand.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Williden Marshal at Marshal's Stand in Un'Goro Crater.", completion = "My team of explorers, researchers, and scientists is the finest in Azeroth, but we need all the help we can get to discover the truth about the crater's history and its denizens.", sourceObjectiveStatus = "unverified-source-field" }
quests[28526] = { id = 28526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Un'Goro Crater!", description = "All able bodied members of the Horde are hereby ordered to report Williden Marshal at Marshal's Stand. You are to provide aid to the Marshal Expeditions' personnel as they uncover the secrets of Un'Goro Crater. The Horde may be able to find a use for the unique beasts and crystals populating the crater.\n\nYou can reach Un'Goro Crater by taking the road from western Tanaris down into the crater and toward Marshal's Stand.\n\nDestiny calls!", sourceObjective = "Report to Williden Marshal at Marshal's Stand in Un'Goro Crater.", completion = "Welcome, {class}. My scientists and explorers will be glad to have your help.", sourceObjectiveStatus = "unverified-source-field" }
quests[28527] = { id = 28527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Silithus!", description = "All able-bodied members of the Horde are hereby ordered to report to Windcaller Proudhorn at Cenarion Hold. You are to aid our Cenarion allies in their battle to turn back Twilight's Hammer. Cho'Gall's minions must not be allowed to dominate Silithus!\n\nYou can reach Silithus by taking the northwestern road out of Un'Goro Crater.\n\nDestiny calls!", sourceObjective = "Report to Windcaller Proudhorn at Cenarion Hold in Silithus.", completion = "Welcome to Cenarion Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[28528] = { id = 28528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Silithus!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Windcaller Proudhorn at Cenarion Hold.\n\nOur Cenarion Circle allies require your assistance to fight back against the Twilight's Hammer onslaught. You can reach Silithus by taking the northwestern road out of the Un'Goro Crater.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Windcaller Proudhorn at Cenarion Hold in Silithus.", completion = "Welcome to Cenarion Hold.", sourceObjectiveStatus = "unverified-source-field" }
quests[28529] = { id = 28529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Writings of the Void", description = "The scrolls are vague and appear to be a piece of a much larger puzzle, but if you are not mistaken, they seem to reveal some of the steps on the path to becoming a demon hunter.\n\nThe dark oaths and rituals necessary for becoming a demon hunter are frowned on by most of the night elves, so this is likely something they would be very interested in keeping quiet.\n\nRanger Glynda Nal'Shea will know what to do with these scrolls.", sourceObjective = "Bring the Writings of the Dark Herald to Ranger Glynda Nal'Shea at Lor'danel.", progress = "How can I help you, {class}?", completion = "Where did you find these?! You haven't shown them to anyone else, have you?\n\nI apologize. You took me off guard. Telarius was a very powerful Demon Hunter, but he was slain during a confrontation with the warden, Maiev, many years ago. You are fortunate that his ghost was only a shade of his former power. I wonder how many have found their way to him in those ruins.\n\nI will see to it that these scrolls make their way to the high priestess immediately. Thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28530] = { id = 28530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scalding Signs", description = "The cauldron looked like it contained concentrated material. If the Winterfall are diluting this stuff directly in the springs, contamination could build up over time... and then the dilution would be less and less effective.\n\nThe spring to the northeast has boiled over with elementals. I thought it was because of the cataclysm, but their appearance could be a reaction to this.\n\nCould you check them for corruption? Hunt a few and bring me any bits of green foreign material they leave behind.", sourceObjective = "Collect 7 pieces of Suspicious Green Sludge from Scalding Springsurges or Boiling Springbubbles.", progress = "What did you find?", completion = "That's quite a bit of it... the Winterfall are slipping further and further. And now we'll have to worry about the other wildlife as well, in time.", sourceObjectiveStatus = "unverified-source-field" }
quests[28531] = { id = 28531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Desolace!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Officer Jankie on the road into Desolace at Tethris Aran.\n\nThe brave soldiers of Nijel's Point are beset by demons and the armies of the Horde, and they need your help. To reach Desolace, travel south on the road from the Charred Vale in the Stonetalon Mountains.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Officer Jankie at Tethris Aran in Desolace.", completion = "I can get you to Nijel's Point quickly! We need all the reinforcements we can get.", sourceObjectiveStatus = "unverified-source-field" }
quests[28532] = { id = 28532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Stonetalon Mountains!", description = "All able bodied members of the Horde are hereby ordered to report to Blood Guard Aldo Rockrain at Silverwind Refuge in Ashenvale. The Horde forces in Stonetalon need your help to drive back the Alliance invaders and protect our people. The blood guard will direct you to the border of Stonetalon.\n\nTo reach Silverwind Refuge, travel into the heart of Ashenvale and join our forces by the lake.\n\nDestiny calls!", sourceObjective = "Report to Blood Guard Aldo Rockrain at Silverwind Refuge in Ashenvale.", completion = "So you're to deploy to Stonetalon? Good, we'll need your abilities to defeat the Alliance there.", sourceObjectiveStatus = "unverified-source-field" }
quests[28533] = { id = 28533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Council's Decision", description = "The High Council is ready to decide on the war with the Neferset tribe.", sourceObjective = "Speak to King Phaoris at Ramkahen in Uldum.", completion = "Very well, it looks like it's time.  Stay and watch if you so please.", sourceObjectiveStatus = "unverified-source-field" }
quests[28534] = { id = 28534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Descendants of the Highborne", description = "Not long after my death, the greed of my people would lead to their exile. A continent away, they would become Quel'dorei, the High Elves. In Quel'thalas they would bathe in the power of their Sunwell, and forget their legacy of desire and greed.\n\nThese distant descendants returned here, drawn by the hand of fate, doomed to repeat history. Hear their tale now, as I have...", sourceObjective = "Speak with the Quel'dorei Spirit.", completion = "We were proud and noble. Our faith in the light protected us, and with the Sunwell, we wanted for nothing.\n\nBecause of that blindness, we came here to repeat the tragedy of history, as our entire race would in time.", sourceObjectiveStatus = "unverified-source-field" }
quests[28535] = { id = 28535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Descendants of the High Elves", description = "Long after my death, my people would suffer an even greater mistake. The High Elves relied on the Sunwell and its glory. Never imagining a world without it, we would never make preparations to deal with such a fate.\n\nLater, when the Sunwell fell to the forces of the undead, what was left of my descendants would be lost and helpless... and the path they would take in response would change them forever.\n\nThe Sin'dorei, still striving for redemption, would return here as well...", sourceObjective = "Speak with the Sin'dorei Spirit.", completion = "We were not naive, as our forefathers were. We were suspicious and cunning and ready for betrayal at every turn.\n\nYet our pride and greed drove us to ruin once more. How many more will be lost to Kel'theril?", sourceObjectiveStatus = "unverified-source-field" }
quests[28536] = { id = 28536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Curse of Zin-Malor", description = "You have seen enough. Know that the Crystal of Zin-Malor brings only ruin to all around it.\n\nLeave this place, if you do not wish to join us.", sourceObjective = "Return to Kelek Skykeeper at Lake Kel'theril in Winterspring.", completion = "The shade! Yes, I saw it too!", sourceObjectiveStatus = "unverified-source-field" }
quests[28537] = { id = 28537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Pursuit of Shades", description = "You say it spoke of a master? Of one who holds Zin-Malor?\n\nThis is grave news. You must act, {class}! I saw the shade fly off to the south. Take the path to the upper ruins, and you may be able to climb the frozen waterfall after it!\n\nAnd do not let your guard down... it may be waiting for you.", sourceObjective = "Pursue and slay the Shade of the Spiritspeaker and obtain any evidence of its master.", progress = "Did you find the shade? Was anything left to indicate its origin?", completion = "Let me see... faintly written, among the engraved incantations, is the name of its master!\n\n\"Umbranse...\"", sourceObjectiveStatus = "unverified-source-field" }
quests[28538] = { id = 28538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cry of the Banshee", description = "So you are to be our savior? Very well then, I will bond myself with you. Through this bond I will be able to see through your eyes and communicate with you in the field.\n\nAccording to the plans you brought to us, the Stormpike have enlisted the aid of SI:7 at Sofera's Naze, to the north. SI:7 are comprised solely of humans - humans that we are able to use to our benefit.\n\nTake my mirror and travel north. Engage in combat with the SI:7 and bring them near death. Once they are injured, use the mirror.", sourceObjective = "Use the Banshee Mirror to capture 10 SI:7 Agents.", completion = "<Melisara's voice pervades your thoughts.>\n\nThe humans will serve us in life and in death. I will be in contact with you shortly.", sourceObjectiveStatus = "unverified-source-field" }
quests[28539] = { id = 28539, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Stonetalon Mountains!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Huntress Jalin at Stardust Spire in Ashenvale.\n\nThe Horde's forces are poised to push into Stonetalon and they must be opposed! You can reach Stardust Spire by traveling to the southern part of Ashenvale Forest, near the border with Stonetalon.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Huntress Jalin at Stardust Spire at the border between Ashenvale and the Stonetalon Mountains.", completion = "The Horde has bored a giant pass into the mountains, and we have few enough sentinels to spare. We have to find a way to stop them!", sourceObjectiveStatus = "unverified-source-field" }
quests[28540] = { id = 28540, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doin' De E'ko Magic", description = "Mau'ari been makin' charms from da spirits of de wilds here for years now. Mau'ari just PLUCK de E'ko right outta de animals, and make charms for de kids, and de adventurers.\n\nOvah to de east, dere be a tall hill surrounded by de shardtooth bears. Up on de hill be Rimepelt, de oldest bear in de woods.\n\nMau'ari need dat bear for her magic. You bring me de bear's big ol' heart.", sourceObjective = "Obtain Rimepelt's Heart.", progress = "You got de bear? Let's see de bear.", completion = "Dis is nice, big heart! If you be interested, Mau'ari tell ya how I be gettin' de E'ko....", sourceObjectiveStatus = "unverified-source-field" }
quests[28542] = { id = 28542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Felwood!", description = "All able bodied members of the Horde are hereby ordered to report to Tenell Leafrunner at the Emerald Sanctuary in Felwood. The Cenarion Circle requires your help to wrest Felwood from the control of demons and other corrupt creatures!\n\nTo reach the Emerald Sanctuary, travel north from Ashenvale and follow the road until you reach the sanctuary.\n\nDestiny calls!", sourceObjective = "Report to Tenell Leafrunner at the Emerald Sanctuary in Felwood.", completion = "Welcome. My brothers and I are dedicated to the redemption and rejuvenation of this once-sacred forest.", sourceObjectiveStatus = "unverified-source-field" }
quests[28543] = { id = 28543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Felwood!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Tenell Leafrunner at the Emerald Sanctuary.\n\nHis order requires your help to redeem Felwood from the demonic influences that rule the forest. Head north from Ashenvale and follow the road into Felwood until you reach the Emerald Sanctuary.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Tenell Leafrunner at the Emerald Sanctuary in Felwood.", completion = "There is much work to do here. The forest is on the mend, but without our help, it will take generations to restore this once-sacred wood.", sourceObjectiveStatus = "unverified-source-field" }
quests[28544] = { id = 28544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Winterspring!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Donova Snowden at Frostfire Hotsprings.\n\nShe requires your help to overcome the threat of the Winterfall furbolg. To reach Winterspring, you must travel east from northern Felwood and traverse Timbermaw Hold.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Donova Snowden at Frostfire Hot Springs in Winterspring.", completion = "Thank goodness you're here. I've discovered the secret of the fierce Winterfall furbolg.", sourceObjectiveStatus = "unverified-source-field" }
quests[28545] = { id = 28545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Winterspring!", description = "All able-bodied members of the Horde are hereby ordered to report to Donova Snowden at Frostfire Hot Springs. Her discoveries about the Winterfall furbolg may be the key to dealing with this threat once and for all.\n\nTo reach the Frostfire Hot Springs in Winterspring, you must travel east from northern Felwood and traverse Timbermaw Hold.\n\nDestiny calls!", sourceObjective = "Report to Donova Snowden at Frostfire Hot Springs in Winterspring.", completion = "Perhaps you can help me make sense of my discoveries about the source of the Winterfall furbolgs' strength.", sourceObjectiveStatus = "unverified-source-field" }
quests[28548] = { id = 28548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Desolace!", description = "All able bodied members of the Horde are hereby ordered to report to Furien at Tethris Aran in Desolace. The brave Horde warriors of Desolace need your help to beat back the armies of the Alliance and ancient demons.\n\nTo reach Tethris Aran, travel south from the Charred Vale in the Stonetalon Mountains.\n\nDestiny calls!", sourceObjective = "Report to Furien at Tethris Aran in Desolace.", completion = "You... arrived just in... time...", sourceObjectiveStatus = "unverified-source-field" }
quests[28549] = { id = 28549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Southern Barrens!", description = "All able bodied members of the Horde are hereby ordered to report to Nura Pathfinder at the High Road in the Southern Barrens. With the recent Alliance victories in the Barrens, our enemies are threatening to cut our supply lines and leave our warriors stranded. We must act!\n\nTo reach the High Road, travel east from Stonetalon Mountains.\n\nDestiny calls!", sourceObjective = "Report to Nura Pathfinder at the High Road in the Southern Barrens.", completion = "You've no doubt seen what the Alliance has done to the Barrens, {class}. If we don't act, there may not be a Horde presence here much longer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28550] = { id = 28550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Southern Barrens!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Commander Walpole at Stonetalon Pass in the Southern Barrens.\n\nOur brave soldiers have made tremendous gains in the Barrens, but they have paid a heavy price! Your efforts are needed to consolidate our gains. You can reach the Southern Barrens from the Stonetalon Mountains by traveling southeast through Greatwood Vale.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Commander Walpole at Stonetalon Pass in northwestern Southern Barrens.", completion = "We face heavy Horde counterattacks daily, {class}. We need every pair of hands we can get to keep them at bay.", sourceObjectiveStatus = "unverified-source-field" }
quests[28551] = { id = 28551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Southern Barrens!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Dockmaster Lewis near Northwatch Hold.\n\nOur brave soldiers have made tremendous gains in the Barrens, but they have paid a heavy price! Your efforts are needed to consolidate our gains. You can reach the docks outside Northwatch Hold by taking a boat from Booty Bay to Ratchet and traveling south along the coast.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Dockmaster Lewis at the docks outside Northwatch Hold in the Southern Barrens.", completion = "We're facing heavy resistance from the Horde, {class}. Any reinforcements are welcome.", sourceObjectiveStatus = "unverified-source-field" }
quests[28552] = { id = 28552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Dustwallow Marsh!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Calia Hastings at Theramore Isle.\n\nYou must aid SI:7's Calia Hastings in uncovering the threats to Theramore, both within the city and beyond its walls. You can reach Theramore Isle by taking the boat from Menethil or traveling across the marsh from the Southern Barrens.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Calia Hastings at Theramore Isle in Dustwallow Marsh.", completion = "Deserters from the city guards are spreading discontent in the ranks. We have to get to the bottom of this before it undermines our defenses.", sourceObjectiveStatus = "unverified-source-field" }
quests[28553] = { id = 28553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Okrilla and the Blasted Lands", description = "I have one final dispatch to deliver to you, {name}.  It comes from Dreadmaul Hold, to the south, in the Blasted Lands.\n\nWarmatron Okrilla is waging battle against the Alliance forces of Nethergarde Keep, and she needs the assistance of a stout {class}.  You immediately sprung to mind.\n\nTravel south into the Blasted Lands, then head west.  Good luck, {name}.", sourceObjective = "Report to Okrilla at Dreadmaul Hold in the Blasted Lands.", completion = "Well, well, well... look what the Ruag dragged in!", sourceObjectiveStatus = "unverified-source-field" }
quests[28554] = { id = 28554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Dustwallow Marsh!", description = "All able bodied members of the Horde are hereby ordered to report to Krog at Brackenwall Village. The marsh is overrun with enemies of many kinds and the Alliance forces there are dangerously strong.\n\nYou can travel to Dustwallow Marsh by following the path from the eastern part of the Southern Barrens toward Brackenwall Village.\n\nDestiny calls!", sourceObjective = "Report to Krog at Brackenwall Village in Dustwallow Marsh.", completion = "If we can get things straightened out here, we have a chance to strike at the Alliance while most of their forces are busy in the Barrens.", sourceObjectiveStatus = "unverified-source-field" }
quests[28555] = { id = 28555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expel the Envoys", description = "<Not yet implemented.>" }
quests[28556] = { id = 28556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Hand", description = "We must break the fingers of the Stormpike if we are to stop their incursion.\n\n<Cromush hands you a small package.>\n\nWithin this package are four high-yield goblin explosives. You are to infiltrate each of the four fingers - Sofera's Naze, Corrahn's Dagger, the Headland and Gavin's Naze - and plant a goblin pocket-nuke at each.\n\nOnce you have done that - as well as all that Melisara asks of you - return to me.", sourceObjective = "Plant a Goblin Pocket-Nuke at Sofera's Naze, Corrahn's Dagger, the Headland and Gavin's Naze.", completion = "Once Melisara is through with you we will detonate the explosives!", sourceObjectiveStatus = "unverified-source-field" }
quests[28557] = { id = 28557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Uldum!", description = "All able-bodied members of the Horde are hereby ordered to report to Adarrah at the Thistleshrub Valley in Tanaris.\n\nAncient texts tell us that Uldum is home to untold riches and treasures beyond compare. Go forth and claim these in the name of the Horde!\n\nYou can reach Adarrah's caravan by traveling to the southwestern part of Tanaris and looking for her in Thistleshrub Valley.\n\nDestiny calls!", sourceObjective = "Speak with Adarrah in Thistleshrub Valley in western Tanaris.", completion = "You could be one of the very first mortals to set foot in Uldum in millenia. Just think of the treasures that await us!", sourceObjectiveStatus = "unverified-source-field" }
quests[28558] = { id = 28558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Uldum!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Adarrah at Thistleshrub Valley in Tanaris.\n\nBe one of the first to enter glorious Uldum and claim its treasures in honor of the Alliance!\n\nYou can reach Adarrah's caravan by traveling to the western reaches of Tanaris.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Speak with Adarrah at Thistleshrub Valley in Tanaris.", completion = "There are wonders just waiting to be discovered beyond this valley. And they will be ours!", sourceObjectiveStatus = "unverified-source-field" }
quests[28559] = { id = 28559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Bloodmyst Isle!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Vorkhan the Elekk Herder at Kessel's Crossing.\n\nThe people of Bloodmyst need your help to deal with treacherous blood elves and dangerous creatures loose on the island. You can reach Kessel's Crossing on Bloodmyst Isle by taking the bridge north from Azuremyst Isle.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Vorkhan the Elekk Herder at Kessel's Crossing on Bloodmyst Isle.", completion = "So you're here to help? Well, there's plenty to do...", sourceObjectiveStatus = "unverified-source-field" }
quests[28560] = { id = 28560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Ghostlands!", description = "All able bodied members of the Horde are hereby ordered to report to Arcanist Vandril at Tranquilien in the Ghostlands.\n\nYour help is needed to turn back the numberless Scourge invaders and secure the help of the Forsaken in fighting our common enemy.\n\nTo reach Tranquilien, follow the road south from Fairbreeze Square and into the Ghostlands.\n\nDestiny calls!", sourceObjective = "Report to Arcanist Vandril at Tranquilien in the Ghostlands.", completion = "Your arrival here is fortuitous, {class}. We cannot fight the Scourge without help.", sourceObjectiveStatus = "unverified-source-field" }
quests[28561] = { id = 28561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nahom Must Hold", description = "As soon as we make our move west in order to attack Neferset City, the enemy will strike us from the east, where we'll be weak.\n\nNahom will be the first to fall, and if it does, Ramkahen will soon follow.\n\nA small detachment is there already.\n\nGet a briefing from them.  I want you to make sure that they hold Nahom until I can send more troops there.", sourceObjective = "Report to the regiment at Nahom in Uldum.", completion = "{name}!  It's you!  My regiment was ambushed on our way here.\n\nOur captain was slain, leaving me in command... until you got here, that is... sir!", sourceObjectiveStatus = "unverified-source-field" }
quests[28562] = { id = 28562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Westfall!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Lieutenant Horatio Lane at the Jansen Stead.\n\nWestfall has been overrun by beggars and transients, leading to a massive increase in criminal activity. Your help is needed to restore order to the populace. You can reach the Jansen Stead in Westfall by traveling west from Elwynn Forest.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Lieutenant Horatio Laine at the Jansen Stead in Westfall.", completion = "Murder, rookie. That's what you're looking at on the ground in front of us.", sourceObjectiveStatus = "unverified-source-field" }
quests[28563] = { id = 28563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Redridge Mountains!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report Watch Captain Parker at Tower Watch in the Redridge Mountains.\n\nCaptain Parker's forces have come under attack from marauding gnolls and orcs. The people of Lakewood are in peril and your aid is needed to safeguard them. Travel east from the border of Elwynn Forest and into the Three Corners area of Redridge to reach Tower Watch.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Watch Captain Parker at Tower Watch in Redridge Mountains.", completion = "Heard Westfall was in some deep doody.\n\n<Parker doesn't even turn to face you.>\n\nWell, we got our own set of problems here. See them gnolls out there? Looks like they're actin' up again. I don't like it. Don't like it one bit.", sourceObjectiveStatus = "unverified-source-field" }
quests[28564] = { id = 28564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Duskwood!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Commander Althea Ebonlocke in Darkshire.\n\nThe commander's watchmen are stretched thin defending against marauding wolves and bands of wild worgen. They cannot hold out for long without your help. You can reach Darkshire in Duskwood by following the road south at the border between Elwynn Forest and the Redridge Mountains.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Commander Althea Ebonlocke at Darkshire in Duskwood.", completion = "You are the help that we requested?\n\n<Althea sighs.>\n\nI suppose you will have to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[28565] = { id = 28565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Wetlands!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Mountaineer Rharen at Dun Algaz.\n\nIn the wake of the cataclysm's destruction, Wetlands has become overrun with wild beasts, orcish raiders, and savage gnolls! To reach the Wetlands, you must travel north from Loch Modan through the dwarven hold of Dun Algaz.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Mountaineer Rharen at Dun Algaz.", completion = "We haven't gotten much in the way of reinforcements lately. We can use every pair of hands we can get.", sourceObjectiveStatus = "unverified-source-field" }
quests[28566] = { id = 28566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decimation", description = "<Melisara's image appears before you.>\n\nThe Stormpike forward camp sits atop Corrahn's Dagger, west of Sofera's Naze. You must enter the camp and slaughter every dwarf that you see. They must be taught what it means to fear and there is no finer lesson than absolute decimation.\n\nNo survivors, {name}. Even their captain - especially their captain - must die.\n\nI will be in contact.", sourceObjective = "Kill Captain Iceheart and 12 Stormpike Soldiers.", sourceObjectiveStatus = "unverified-source-field" }
quests[28567] = { id = 28567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Loch Modan!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Pilot Hammerfoot at South Gate Outpost.\n\nThe destruction of the Stonewrought Dam and the resurgence of the kobolds and troggs has the mountaineers stretched thin. Reinforcements are desperately needed! Travel east through South Gate Pass from eastern Dun Morogh to reach South Gate Outpost.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Pilot Hammerfoot at South Gate Outpost in Loch Modan.", completion = "Have our leaders finally heard my pleas? We're down to just a handful of pilots and mountaineers to defend Loch Modan.", sourceObjectiveStatus = "unverified-source-field" }
quests[28568] = { id = 28568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Silverpine Forest!", description = "All able-bodied members of the Horde are hereby ordered to report to Grand Executor Mortuus at Forsaken High Command in Silverpine Forest.\n\nNow, more than ever, your help is needed in routing the enemy infestation of the region and conquering the port of Gilneas!\n\nTo reach Forsaken High Command you must travel south through Tirisfal Glades and enter Silverpine Forest. From there, follow the road south until you reach Forsaken High Command.\n\n Destiny calls!", sourceObjective = "Report to Grand Executor Mortuus at Forsaken High Command in Silverpine Forest.", completion = "Most excellent! A new recruit has arrived. There is much to do... much to do I say.", sourceObjectiveStatus = "unverified-source-field" }
quests[28569] = { id = 28569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bogpaddle Bullet", description = "I've heard stories about a road to the Swamp of Sorrows.  Mysterious tales of a meandering mountain pathway that completely bypasses Redridge and poops you right out into Bogpaddle!\n\nIf you run out of things to do, I suppose you'll have to leave.  And we'll all be sad.  When you do leave, talk to Sharon Boomgetter in the southeastern corner of the Steppes.  She'll give you a ride.\n\n<Oralius tilts his head, as if listening to something.>\n\nWinky?  WINKY!  NO!", sourceObjective = "Speak with Sharon Boomgetter in the southeastern corner of Burning Steppes to ride the Bogpaddle Bullet to the Swamp of Sorrows. Then speak with Trade Baron Silversnap in Bogpaddle.", completion = "Time is money, {class}... and I've got plenty of each.\n\nWhat can I do for you?", sourceObjectiveStatus = "unverified-source-field" }
quests[28570] = { id = 28570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bogpaddle Bullet", description = "You're quite the {race}, aren't you?  Look at you... you're all grown up already.  And we only just met!\n\nI know how it'll go... soon you'll run out of things to do here at Flame Crest.  You'll promise to come back.  But you never will.\n\nKibler's seen it all before.\n\nWhen you do leave, talk to Sharon Boomgetter in the southeastern corner of the Steppes.  She'll give you a ride on the bullet.\n\nWhat?  Oh, it's just a rocket.  Perfectly safe.", sourceObjective = "Speak with Sharon Boomgetter in the southeastern corner of Burning Steppes to ride the Bogpaddle Bullet to the Swamp of Sorrows. Then speak with Trade Baron Silversnap in Bogpaddle.", completion = "Time is money, {class}... and I've got plenty of each.\n\nWhat can I do for you?", sourceObjectiveStatus = "unverified-source-field" }
quests[28571] = { id = 28571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Hillsbrad Foothills!", description = "All able bodied members of the Horde are hereby ordered to report to High Executor Darthalia at Southpoint Gate in Hillsbrad Foothills. The Forsaken war machine marches ever onward, securing Lordaeron for the Horde!\n\nTo reach Southpoint Gate you must follow the road south through Silverpine Forest and take the east fork leading into Hillsbrad Foothills.\n\nOnward, <brother/sister>! Destiny calls!", sourceObjective = "Report to High Executor Darthalia at Southpoint Gate in Hillsbrad Foothills.", completion = "I was wondering when reinforcements would show up. Suit up, {name}. It's time to dispense some justice!", sourceObjectiveStatus = "unverified-source-field" }
quests[28572] = { id = 28572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Arathi Highlands!", description = "All able bodied members of the Horde are hereby ordered to report to Dark Ranger Alina at Galen's Fall. The Dark Lady's forces need your help to expand the dominions of the Horde and drive back the Alliance interlopers.\n\nTo reach the Arathi Highlands, travel east from Hillsbrad Foothills and follow the road past Thoradin's Wall.\n\nDestiny calls!", sourceObjective = "Report to Dark Ranger Alina at Galen's Fall in Arathi Highlands.", completion = "At last, the Warchief's reinforcements have arrived. The Dark Lady has plans for you, as she does for us.", sourceObjectiveStatus = "unverified-source-field" }
quests[28573] = { id = 28573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Arathi Highlands!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Captain Nials at Refuge Pointe.\n\nAncient Stromgarde's honor must be redeemed! Too long have ogres and criminals sullied its streets. Travel north from the Wetlands and cross the Thandol Span to reach Arathi. Follow the road to Refuge Pointe and present yourself to the captain.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Captain Nials at Refuge Pointe in Arathi Highlands.", completion = "Would that you were a company, but we'll have to make do with with what we have.", sourceObjectiveStatus = "unverified-source-field" }
quests[28574] = { id = 28574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: The Hinterlands!", description = "All able bodied members of the Horde are hereby ordered to report to Elder Torntusk at Revantusk Village.\n\nNow that the Wildhammer dwarves have officially thrown in their lot with the Alliance, they have made themselves our enemies. They must be defeated!\n\nTo reach Revanktusk Village, cross into the Hinterlands from the mountain pass in eastern Hillsbrad Foothills and make your way to the eastern coast.\n\nDestiny calls!", sourceObjective = "Report to Elder Torntusk at Revantusk Village in the Hinterlands.", completion = "Have you come to help us against the Wildhammers? The Warchief knows that what happens here will be important to the Horde's future.", sourceObjectiveStatus = "unverified-source-field" }
quests[28575] = { id = 28575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Western Plaguelands!", description = "All able bodied members of the Horde are hereby ordered to report to Koltira Deathweaver at Andorhal.\n\nThe Alliance forces are advancing into the ruined city of Andorhal, seeking to claim it for themselves. We must counter their them before they can gain a foothold there!\n\nCross the Bulwark at the eastern end of Tirisfal Glades and follow the roads southest to Andorhal and meet up with our forces there.\n\nDestiny calls!", sourceObjective = "Report to Koltira Deathweaver at Andorhal in the Western Plaguelands.", completion = "Is this all the warchief can spare? Don't worry, you'll be put to good use.", sourceObjectiveStatus = "unverified-source-field" }
quests[28576] = { id = 28576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Western Plaguelands!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Thassarian at Andorhal.\n\nOn the heels of our early victories in Andorhal, the Forsaken have decided to launch a counterattack. Your help is needed to beat back the Scourge and Horde and reclaim lost Andorhal.\n\nTo reach Andorhal, travel north through the Hillsbrad Foothills and follow the road beyond Chillwind Camp.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Thassarian at Andorhal in the Western Plaguelands.", completion = "There is much to be done here. Both of our enemies are relentless and would slaughter us without mercy the moment we sheathe our blades.", sourceObjectiveStatus = "unverified-source-field" }
quests[28577] = { id = 28577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Eastern Plaguelands!", description = "All able bodied members of the Horde are hereby ordered to report to Fiona on the east bank of the Thondroril River.\n\nThe Argent Crusade has reinforced its presence in the Plaguelands and it needs your help to consolidate its victories.\n\nCross the Thondroril River at the eastern border of the Western Plaguelands and look for Fiona on the far bank.\n\nDestiny calls!", sourceObjective = "Report to Fiona on the east bank of the Thondroril River in the Eastern Plaguelands.", completion = "Perhaps you can help, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28578] = { id = 28578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Eastern Plaguelands!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Fiona on the east bank of the Thondroril River.\n\nThe Argent Crusade needs your help to win back the Eastern Plaguelands from the grasp of the Scourge.\n\nTo reach the Eastern Plaguelands, cross the Thondroril River from the Western Plaguelands and look for Fiona on the eastern bank.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Fiona on the eastern bank of the Thondroril River in the Eastern Plaguelands.", completion = "Perhaps you can help, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28579] = { id = 28579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Badlands!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Gek Nozzlerocket at Light's Hope Chapel in the Eastern Plaguelands.\n\nYour help is needed to survey the damage done by Deathwing, and the disposition of Horde forces in the Badlands.\n\nGek has agreed to provide transportation to the Badlands via rocket, in exchange for your help. Look for him at Light's Hope Chapel in the Eastern Plaguelands.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Gek Nozzlerocket at Light's Hope Chapel in the Eastern Plaguelands.", completion = "You must be here to help Fuselight! Let's get you to the Badlands right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[28580] = { id = 28580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Badlands!", description = "All able bodied members of the Horde are hereby ordered to report to Gek Nozzlerocket at Light's Hope Chapel in the Eastern Plaguelands.\n\nThe Alliance is desperate to gain a foothold in the Badlands. Your duty will be to keep them at bay and learn about the destruction wrought by Deathwing.\n\nGek has agreed to provide transportation to the Badlands by rocket. Meet with him at Light's Hope Chapel.\n\nDestiny calls!", sourceObjective = "Report to Gek Nozzlerocket at Light's Hope Chapel in the Eastern Plaguelands.", completion = "Sure, I can get you to the Badlands, but when you get there, I want you to agree to help my comrades.", sourceObjectiveStatus = "unverified-source-field" }
quests[28581] = { id = 28581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warchief's Command: Searing Gorge!", description = "All able bodied members of the Horde are hereby ordered to report to Jack Rockleg at Thorium Advance.\n\nThe Shattered Hand reports that the Dark Iron dwarves of the Searing Gorge seem to be preparing for something. Your duty is to learn all you can about their scheming and put a halt to it.\n\nYou can reach the Searing Gorge by following the road west from the Badlands.\n\nDestiny calls!", sourceObjective = "Report to Jack Rockleg at Thorium Advance in the Searing Gorge.", completion = "We, too, are suspicious of the Dark Irons' recent activities.", sourceObjectiveStatus = "unverified-source-field" }
quests[28582] = { id = 28582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: Searing Gorge!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Jack Rockleg at Thorium Advance.\n\nSI:7 reports that the Dark Iron dwarves of the Searing Gorge seem to be preparing to attack. Your duty is to learn all you can about their scheming and put a halt to it.\n\nYou can reach the Searing Gorge by following the road west from the Badlands.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Report to Jack Rockleg at Thorium Advance in the Searing Gorge.", completion = "We, too, are suspicious of the Dark Irons.", sourceObjectiveStatus = "unverified-source-field" }
quests[28583] = { id = 28583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krazzworks", description = "This new shredder design is tops, {name}. Tops! Next step is to protect my intellectual property. There are patents to file, traders to mark, ceases to desist. Oh, and the bribes!\n\nHere, take this patent application to Captain Krazz at the Krazzworks. He survived the destruction of his zeppelin, so he's probably hungry for new business opportunities.\n\nThe Krazzworks is due north of here, atop a perfectly safe mountain peak. Go ahead, kid. Chop chop!", sourceObjective = "Take the Patent Application to Captain Krazz at the Krazzworks in Twilight Highlands.", progress = "I know you! You were on the Zeppelin with me on the way in.", completion = "What's this? The \"{name}-o-matic:\" a shredder with an integrated missile platform?\n\nBah! Already patented by Labor Captain Grabbit in Azshara. Worthless!\n\nWhat I really need is a machine that knocks dwarves from the sky.", sourceObjectiveStatus = "unverified-source-field" }
quests[28584] = { id = 28584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quality Construction", description = "Look here, chief, if it weren't for this bumbly idiot across from me, the Krazzworks would be holding up just fine.\n\nUnfortunately for everyone involved, \"Fancypants\" Rothman here decided to deploy the place on top of a mountain! I mean really, who does that?\n\nSo, we got leaks all over the place due to faulty valves. Think you could take this blast tape and seal 'em up for me?", sourceObjective = "Use the Blast Tape to seal 10 Faulty Valves.", progress = "Look, I'm just a simple cartographer, but according to my estimates, not to mention what my eyes are telling me, there are a few more faulty valves that need to be sealed.", completion = "There you go. Now hows about we use this blast tape on Rothman's mouth?", sourceObjectiveStatus = "unverified-source-field" }
quests[28586] = { id = 28586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pool Pony Rescue", description = "This jerk across from me is getting all of our people killed!\n\nBrett \"the Bummer\" unpacked the Krazzworks in the wrong place and now it's highly unstable. The explosions from the instability are throwing our laborers off of the platforms and into the water below.\n\nYou don't mind flying down there and rescuing them with some pool ponies, {name}?", sourceObjective = "Use the Pool Ponies to rescue 10 Krazzworks Laborers that have fallen into the water.", progress = "Maybe you'd be willing to fly back down there and rescue a few more of our laborers?", completion = "Thanks, {name}! Now if we could just get the Krazzworks stable so that our people would stop being thrown off of the platforms.", sourceObjectiveStatus = "unverified-source-field" }
quests[28587] = { id = 28587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aid of the Frostwolf", description = "I will study the Stormpike battle plans and prepare for an assault. I need you to go to Alterac Valley and enlist the aid of the Frostwolf Clan: the very clan of our former warchief, Thrall. They will help us battle the Stormpike dwarves! Together, we will crush the invaders and see them driven out of Lordaeron for good!\n\nGo now, {name}. Alterac Valley is northeast of Tarren Mill. Find Voggah Deathgrip and tell him that the Horde requires the aid of the Frostwolf!\n\nLOK'TAR!", sourceObjective = "Speak to Voggah Deathgrip at Alterac Mountains in Hillsbrad Foothills.", completion = "You come from Tarren Mill? You reek of death...", sourceObjectiveStatus = "unverified-source-field" }
quests[28588] = { id = 28588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildhammer Infestation", description = "While these two idiots argue about who royally messed up here, we've got a full-scale invasion of the Krazzworks taking place!\n\nThose no-good Wildhammer are all over the place. Get out there and clear the Krazzworks of those smelly ale-guzzling pests.", sourceObjective = "Slay 10 Wildhammer Raiders.", progress = "What? That's all you've killed?\n\nGet back out there and take care of the rest!", completion = "You got the chops for killing dwarves, that's for sure, {name}. This is a good thing.\n\nNext up, more dwarf slayage!", sourceObjectiveStatus = "unverified-source-field" }
quests[28589] = { id = 28589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everything But the Kitchen Sink", description = "You gotta do something about them Wildhammer Stormtalons. They're tearing us up!\n\nProblem is, we're out of ammo, so we had to improvise. We loaded up my Krazz Cannons with all kinds of stuff: pool ponies, Kaja'Cola cans, food containers, fuelcells, tires... you get the picture.\n\nBasically, everything but the kitchen sink.\n\nThink you're in the mood for some target practice?", sourceObjective = "Slay 15 Wildhammer Stormtalons.", completion = "That's the spirit! Must be pretty humiliating being shot down by junk.", sourceObjectiveStatus = "unverified-source-field" }
quests[28590] = { id = 28590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reprisal", description = "I happen to know some Alliance scum that have somethin' coming to them. And they have something that belongs to us. I've authorized an all out assault on Highbank.\n\nBoard the Skyshredder and join the assault. Patch will fill you in on the details as you arrive.", sourceObjective = "Speak to Patch aboard the Skyshredder circling Highbank.", completion = "Good to have you, {name}. Ready to sow some chaos?", sourceObjectiveStatus = "unverified-source-field" }
quests[28591] = { id = 28591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off The Wall", description = "You look like a <man/girl> who likes some action. Get on one of those turrets and lay waste to their defenses on the wall.\n\nBe quick about it, will you? Before we go up in a big ball of fire preferably.", sourceObjective = "Kill 80 Highbank Marksman, 12 Highbank Cannoneers, and 4 Highbank Cannons with a Skyshredder Turret.", completion = "Marvels of modernized goblin destructivity, eh? I love these babies.", sourceObjectiveStatus = "unverified-source-field" }
quests[28592] = { id = 28592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parting Packages", description = "I'm sure Patch has some grand scheme in mind, but this wouldn't be an assault if we didn't leave some explosive presents behind.\n\nGet down there and plant some of these explosives on the boat, in the keep entrance, and in one of those northern towers. That should be enough to leave them reeling.\n\nWe're heading down to the ground as well. Meet us at the eastern tower when you're through.", sourceObjective = "Set bombs on the boat, in the keep entrance, and in one of the northern towers.", completion = "Hahah! Wonderful show.\n\nThat should be a proper welcome to the highlands.", sourceObjectiveStatus = "unverified-source-field" }
quests[28593] = { id = 28593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Utmost Importance", description = "When Garrosh's zeppelin went down, so did the induction samophlange that you recovered for us in Azshara. The Alliance have it somewhere in that keep, and Krazz wants it back.\n\nThe basement of the keep would be my best guess, so start there. When you get your hands on it, bring it back to me near the eastern tower.", sourceObjective = "Recover the Induction Samophlange.", progress = "Krazz is waitin'. Keep it moving.", completion = "Brilliant! Krazz will love you something mighty for bringing this one home. Good on you.", sourceObjectiveStatus = "unverified-source-field" }
quests[28594] = { id = 28594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Highbank, Crybank", description = "Get down there and make a mess of those Alliance rabble. Any of'm will do. I just want'm scattered while you're in there after the real target.\n\nFind us near the eastern tower when you're done.", sourceObjective = "Kill 10 Highbank defenders.", progress = "A few more than that please. By the looks of them, they haven't had enough of us yet.", completion = "And that's how it's done. Scattered to the wind. Not quite the fighting force they boast themselves to be, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[28595] = { id = 28595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krazz Works!", description = "That's it. We're all wrapped up. Let's ship out.\n\nNewt's got some gyrocopters tethered at the top of the tower. Go meet up with her for a quick trip back to Krazzworks. We'll mop up here.", sourceObjective = "Speak to Newt to secure a ride back to Krazzworks, then give the Induction Samophlange to Captain Krazz.", progress = "Tell me you came through? You always come through. Show me my beauty!", completion = "Now that's what I wanted to see! I'll have this fleet back up in no time with this beauty.\n\nYou know just how I like it, {name}. I know just how you like it too - take this.", sourceObjectiveStatus = "unverified-source-field" }
quests[28596] = { id = 28596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Highbank!", description = "Welcome to the highlands, soldier. You're here just in time.\n\nHorde troops just launched an assault from the air. Step up and do something about it. Clear them out!", sourceObjective = "Kill 10 Horde attackers within Highbank.", progress = "You'll have to kill a few more than that, soldier.", completion = "That's more like it. We should be able to mop this up from here.", sourceObjectiveStatus = "unverified-source-field" }
quests[28597] = { id = 28597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burnin' at Both Ends", description = "Har! We get to jump right inta the action, {name}. Looks like Highbank has whatcha call a zeppelin problem: that airship is poundin' the crap outta the walls.\n\nListen, I've got me an idear so stupid it's genius. I just need some cannon powder.\n\nCollect as much as you can find around Highbank an' meet me by the trade area!", sourceObjective = "Collect 10 bags full of Cannon Powder.", progress = "I need more powder! Get me more powder! More more more!", completion = "Aye, that'll do 'er.\n\n<Flintlocke stuffs some of the powder in his mouth.>\n\nOhhh, fresh. Heady. Redridge fine grain with a hint of Westfall sulphur and a mild aftertaste. Highbank gets the good stuff.", sourceObjectiveStatus = "unverified-source-field" }
quests[28598] = { id = 28598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiming High", description = "Lookie here, {name}. I found the biggest gun in Highbank! We're gonna try a technique handed down ta me by my pappy, from his pappy, from his pappy, shortly before he got blowed up.\n\nIt's called the \"{class}-shot.\"\n\nYou take a {race} {class}, and load <him/her> inta a gigantic cannon, and then ya - oh relax. This usually works.\n\nTake these explosives, then wait here next ta me. As soon as that blimpy comes around I'll blast you onto tha deck. Plant the explosives in 'er belly and, oh I dunno, make it up as you go.", sourceObjective = "Wait for Fargo Flintlocke to get you onto the zeppelin and then set his explosives in its lower chamber.", progress = "Ain't no problem a bomb can't solve.", completion = "<Flintlocke wipes tears from his eyes.>\n\nOh, {name}. {name}!\n\nThat ... were beautiful.", sourceObjectiveStatus = "unverified-source-field" }
quests[28599] = { id = 28599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurdran's Waitin'", description = "It looks like the attack stopped, {name}. Which is a shame, 'cuz we never got to use the {class}-rocket.\n\nAnyways, Kurdran Wildhammer is up in the top of the keep an' I'm sure he'll be wantin' to gives ya a hero's welcome. Yeh earned it! Go talk to 'im!\n\nI'll move on ahead and scout out the beach.", sourceObjective = "Speak to Kurdran Wildhammer inside of the Highbank Keep in Twilight Highlands.", completion = "The King himself sent you? Good to hear that Stormwind is secure.\n\nI was expecting more in the way of troops, but word is that the Alliance fleet was ambushed by the Horde on the way here. They gave as good as they got, but the fleet is in shambles.\n\nIf we're to make any forward progress here in the Highlands, we're going to need the help of heroes like you.", sourceObjectiveStatus = "unverified-source-field" }
quests[28600] = { id = 28600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Matters of Loyalty", description = "I have no authority over such matters. You must speak to our leader, Drek'Thar. I have already sent word of your arrival to Frostwolf Keep. Drek'Thar will be out to speak with you personally.", sourceObjective = "Speak to Drek'Thar.", completion = "<High Warlord Cromush's face turns white.>\n\nTHEY HAVE FORSAKEN US? THEY HAVE FORSAKEN THE HORDE? This cannot be!\n\nI...\n\n<Cromush falls to one knee.>\n\nI... I WILL BE FINE. We will do this without their aid. To hell with the Frostwolf!", sourceObjectiveStatus = "unverified-source-field" }
quests[28602] = { id = 28602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Be Prepared", description = "Every adventurer worth their salt knows never to step foot in a cave, dungeon, crypt or tomb without an ample supply of rope... right?\n\nWell, mine was in that wagon full of explosives that you set off.\n\nHow about searching around here and seeing if you can't find some.", sourceObjective = "Collect 6 Rope Pieces.", progress = "How goes the search?", completion = "Something tells me I'm going to need this.", sourceObjectiveStatus = "unverified-source-field" }
quests[28603] = { id = 28603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltration", description = "For your next mission I want you to travel west to the Headland and infiltrate the Stormpike training grounds. Though there are hundreds of Stormpike trainees there, one of my banshees will disguise you to look like one of the humans captured earlier, allowing you to walk freely among the enemy.\n\nEnter the Headland and find the Stormpike instructors. Once found, coerce them into attacking you! When they attack, kill them. With their instructors dead, they will be unable to train more soldiers!", sourceObjective = "Kill Instructor Rufus, Drill Sergeant Magnus and Captain Crudbeard.", sourceObjectiveStatus = "unverified-source-field" }
